export const KENNIS_SITE = [{"id":"kennisbank/bonnetjes-bewaren#0","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"Home / Kennisbank / Bonnetjes bewaren  Door Koen Avezaat en Daan Evers. Bijgewerkt in oktober 2026, 4 minuten lezen. Als ondernemer heb je een wettelijke bewaarplicht. De Belastingdienst moet je administratie jaren later nog kunnen controleren. Maar wat valt daar precies onder, en hoe lang moet je alles bewaren?"},
{"id":"kennisbank/bonnetjes-bewaren#1","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?: Hoe lang moet je bewaren?","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"De hoofdregel: 7 jaar . Voor gegevens over onroerende zaken, zoals een bedrijfspand, geldt een langere termijn van 10 jaar."},
{"id":"kennisbank/bonnetjes-bewaren#2","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?: Wat moet je bewaren?","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"Verkoopfacturen die je naar klanten stuurt Inkoopfacturen en bonnetjes van zakelijke uitgaven Bankafschriften van je zakelijke rekening Contracten en overeenkomsten met klanten en leveranciers Je btw-aangiftes en aangiftes inkomstenbelasting Je urenregistratie en kilometerregistratie, als je die bijhoudt"},
{"id":"kennisbank/bonnetjes-bewaren#3","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?: Mag een foto of scan ook?","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"Ja. Je mag je administratie digitaal bewaren, zolang de gegevens volledig en leesbaar zijn en de Belastingdienst ze binnen redelijke tijd kan inzien. Een duidelijke foto van een bonnetje in je boekhoudapp is dus prima. Zorg wel dat bedrag, datum, leverancier en btw goed leesbaar zijn."},
{"id":"kennisbank/bonnetjes-bewaren#4","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?: Tips om het jezelf makkelijk te maken","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"Direct een foto maken. Thermisch papier vervaagt, en bonnetjes raken kwijt in je jaszak. Vraag om een factuur op je bedrijfsnaam bij grotere aankopen. Gebruik alleen je zakelijke rekening voor zakelijke uitgaven. Dat maakt de koppeling met je administratie overzichtelijk. Stuur digitale facturen direct door naar je boekhoudmailadres, in plaats van ze te laten liggen in je inbox."},
{"id":"kennisbank/bonnetjes-bewaren#5","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?: Aan welke eisen moet een factuur voldoen?","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"Wil je de btw op een aankoop terugvragen, dan heb je een factuur nodig die aan de wettelijke eisen voldoet. Een betaling op je bankafschrift alleen is niet genoeg. Op een volledige factuur staan in elk geval: naam en adres van de leverancier en van jou als koper; het btw-nummer van de leverancier; een factuurnummer en de factuurdatum; een omschrijving van wat je gekocht hebt; het bedrag zonder btw, het btw-tarief en het btw-bedrag. Voor aankopen tot €100 inclusief btw mag een leverancier een vereenvoudigde factuur geven, zoals een kassabon. Daar hoeft jouw naam niet op te staan. Bij grotere aankopen vraag je dus altijd om een factuur op je bedrijfsnaam."},
{"id":"kennisbank/bonnetjes-bewaren#6","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?: Bonnetje kwijt: wat nu?","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"Vraag de leverancier om een kopie, of zoek de factuur op in je mail of in je account bij de webshop. Lukt dat niet, dan kun je de kosten soms toch aftrekken van je winst, als je met je bankafschrift en een korte toelichting aannemelijk maakt dat het zakelijk was. De btw kun je zonder factuur niet terugvragen. Een vergeten bonnetje kost je dus direct 21% van het bedrag."},
{"id":"kennisbank/bonnetjes-bewaren#7","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?: Zakelijk en privé door elkaar","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"Gebruik je iets zowel zakelijk als privé, zoals je telefoon of laptop? Dan mag je alleen het zakelijke deel aftrekken. Bewaar de factuur gewoon, en spreek met je boekhouder af welk deel zakelijk is. Betaal privé-uitgaven het liefst niet met je zakelijke rekening. Gebeurt dat toch, zet er dan een notitie bij, zodat het als privé wordt geboekt."},
{"id":"kennisbank/bonnetjes-bewaren#8","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?: Papier na het scannen weggooien?","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"Je mag papieren documenten omzetten naar een digitale versie en het papier daarna weggooien, zolang de digitale versie volledig, leesbaar en ongewijzigd is. Voor een paar stukken, zoals de balans, geldt dat niet: die bewaar je in de originele vorm. Ontvang je een factuur digitaal, als pdf of e-factuur, dan bewaar je die digitale versie. Een uitdraai is dan niet genoeg."},
{"id":"kennisbank/bonnetjes-bewaren#9","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?: Wat als je administratie niet compleet is?","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"Kun je bij een controle je cijfers niet onderbouwen, dan mag de Belastingdienst je winst schatten. In sommige gevallen moet jij dan bewijzen dat die schatting niet klopt. Dat heet omkering van de bewijslast, en dat is lastig. Een complete administratie is dus je beste bescherming. De bewaarplicht van 7 jaar blijft ook gelden als je stopt met je bedrijf."},
{"id":"kennisbank/bonnetjes-bewaren#10","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?: Welke kosten zijn niet of beperkt aftrekbaar?","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"Bewaar je bonnetjes altijd, maar weet dat niet elke uitgave volledig aftrekbaar is: Eten, drinken, representatie en congressen: dit zijn gemengde kosten. Je mag 80% aftrekken, of alles boven een drempel van €5.700 (2026). Voor de meeste zzp’ers is de 80%-regeling gunstiger. De btw op eten en drinken in de horeca kun je niet terugvragen. Kleding: alleen aftrekbaar als het echte werkkleding is, zoals veiligheidsschoenen, of als er een logo van je bedrijf op staat van minstens 70 cm². Boetes , zoals een verkeersboete, zijn nooit aftrekbaar. Telefoon en internet: alleen het zakelijke deel."},
{"id":"kennisbank/bonnetjes-bewaren#11","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?: Moet ik ook bonnetjes onder de €10 bewaren?","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"Ja. Elk bedrag telt mee voor je kosten en je btw. Kleine bedragen tellen over een jaar flink op."},
{"id":"kennisbank/bonnetjes-bewaren#12","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?: Is een bankafschrift genoeg?","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"Voor de btw niet: daarvoor heb je een factuur nodig. Voor je winst is een bankafschrift alleen zwak bewijs. Bewaar dus altijd de factuur of bon. Bij ons: je maakt een foto in de app of stuurt je factuur door per mail. Wij koppelen het aan de juiste banktransactie en bewaren alles digitaal, zodat je administratie altijd compleet en controleerbaar is. Geschreven door Koen Avezaat en Daan Evers Boekhouders en oprichters van Avezaat & Evers. Dagelijks bezig met de administratie en aangiftes van zzp’ers. Over ons Dit artikel geeft algemene informatie. Voor je eigen situatie kun je het beste even contact met ons opnemen, of kijken op de website van de Belastingdienst."},
{"id":"kennisbank/bonnetjes-bewaren#13","groep":"Kennisbank","titel":"Welke bonnetjes moet je bewaren, en hoe lang?: Nooit meer zoeken naar bonnetjes","bron":"/kennisbank/bonnetjes-bewaren","tags":"","tekst":"Foto maken in de app, wij doen de rest. Voor €80 per maand. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"kennisbank/btw-aangifte-deadlines#14","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"Home / Kennisbank / Btw-aangifte  Door Koen Avezaat en Daan Evers. Bijgewerkt in oktober 2026, 4 minuten lezen. Ben je btw-plichtig als zzp’er? Dan doe je meestal vier keer per jaar btw-aangifte: één keer per kwartaal. In de aangifte geef je door hoeveel btw je hebt gerekend aan je klanten, en hoeveel btw je zelf hebt betaald op zakelijke kosten. Het verschil betaal je aan de Belastingdienst, of krijg je terug."},
{"id":"kennisbank/btw-aangifte-deadlines#15","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: De deadlines per kwartaal","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"Aangifte doen én betalen moet uiterlijk op de laatste dag van de maand na afloop van het kwartaal. Kwartaal Periode Uiterste datum Q1 januari – maart 30 april Q2 april – juni 31 juli Q3 juli – september 31 oktober Q4 oktober – december 31 januari Let op: het bedrag moet ook vóór die datum op de rekening van de Belastingdienst staan. Betaal dus een paar dagen eerder. Zet alle deadlines in je agenda Btw-aangifte, aangifte inkomstenbelasting, KOR en jaareinde. Je krijgt een week van tevoren een herinnering, en de agenda werkt zich vanzelf bij. Gratis. iPhone of Mac Google Agenda Outlook Download"},
{"id":"kennisbank/btw-aangifte-deadlines#16","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: Wat gebeurt er als je te laat bent?","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"Doe je te laat aangifte of betaal je te laat, dan kan de Belastingdienst een boete opleggen. Dat geldt ook als je per saldo niets hoeft te betalen. Daarnaast kan er belastingrente bijkomen. Te laat zijn is dus altijd zonde van je geld."},
{"id":"kennisbank/btw-aangifte-deadlines#17","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: Wat heb je nodig voor de aangifte?","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"Al je verkoopfacturen van het kwartaal Je inkoopfacturen en bonnetjes met btw Je zakelijke bankafschriften, om te controleren of alles compleet is Hoe completer je administratie, hoe meer btw je terug kunt vragen. Een vergeten bonnetje is letterlijk geld laten liggen."},
{"id":"kennisbank/btw-aangifte-deadlines#18","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: En als je de kleineondernemersregeling (KOR) gebruikt?","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"Met de KOR reken je geen btw aan je klanten en hoef je in principe geen btw-aangifte te doen. Je kunt dan ook geen btw terugvragen op je kosten. Of de KOR voor jou gunstig is, hangt af van je omzet, je klanten en je investeringen. Lees wanneer de KOR loont."},
{"id":"kennisbank/btw-aangifte-deadlines#19","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: Zo bereken je wat je moet betalen","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"Je betaalt het verschil tussen de btw die je aan klanten hebt gerekend en de btw die je zelf hebt betaald op zakelijke kosten. Omzet in het kwartaal (excl. btw) €15.000 Btw gerekend aan klanten (21%) €3.150 Btw betaald op kosten, zoals laptop, telefoon en materiaal – €600 Te betalen aan de Belastingdienst €2.550 Is de btw op je kosten hoger dan de btw die je rekent, bijvoorbeeld in een kwartaal met een grote investering? Dan krijg je het verschil terug."},
{"id":"kennisbank/btw-aangifte-deadlines#20","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: Factuurdatum telt, niet de betaling","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"De meeste zzp’ers gebruiken het factuurstelsel. Dan hoort de btw in de aangifte van het kwartaal waarin je de factuur stuurt, ook als je klant pas later betaalt. Een factuur van 28 maart gaat dus in de aangifte over het eerste kwartaal. Bedrijven die vooral aan particulieren verkopen, zoals winkels, horeca en kappers, gebruiken meestal het kasstelsel: dan telt het moment van betaling. Betaalt een klant helemaal niet? Dan kun je de btw die je al hebt afgedragen terugvragen zodra de factuur oninbaar is, en uiterlijk één jaar na de uiterste betaaldatum."},
{"id":"kennisbank/btw-aangifte-deadlines#21","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: Welke btw mag je aftrekken, en welke niet?","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"Je mag de btw aftrekken op kosten die je maakt voor je bedrijf, mits je een goede factuur hebt. Een paar uitzonderingen: Eten en drinken in een restaurant of café: de btw daarop is niet aftrekbaar, ook niet bij een zakenlunch. Privégebruik: gebruik je iets ook privé, dan trek je alleen het zakelijke deel af. Vrijgestelde omzet: doe je werk dat vrijgesteld is van btw, zoals veel medische zorg, dan mag je de btw op de kosten daarvoor niet aftrekken."},
{"id":"kennisbank/btw-aangifte-deadlines#22","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: Foutje gemaakt in een eerdere aangifte?","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"Is het verschil €1.000 of minder, dan corrigeer je het in je volgende aangifte. Gaat het om meer dan €1.000, dan dien je een suppletie in: een aparte correctie bij de Belastingdienst. Doe dat zo snel mogelijk nadat je de fout ontdekt."},
{"id":"kennisbank/btw-aangifte-deadlines#23","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: Zet de btw apart","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"De btw die je ontvangt, is niet van jou. Zet hem direct apart op een spaarrekening. Zo heb je het geld klaarstaan als de aangifte komt, en kom je niet in de problemen in een kwartaal waarin je minder omzet hebt."},
{"id":"kennisbank/btw-aangifte-deadlines#24","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: Moet ik aangifte doen als ik niets heb verkocht?","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"Ja. Krijg je een uitnodiging voor de btw-aangifte, dan doe je altijd aangifte, ook als alles nul is. Anders kun je een boete krijgen."},
{"id":"kennisbank/btw-aangifte-deadlines#25","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: Wat is het verschil tussen mijn btw-id en mijn omzetbelastingnummer?","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"Je btw-identificatienummer (btw-id) zet je op je facturen en website. Je omzetbelastingnummer gebruik je alleen voor contact met de Belastingdienst en je aangifte. Zet dat laatste dus niet op je facturen."},
{"id":"kennisbank/btw-aangifte-deadlines#26","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: Kan ik per maand aangifte doen in plaats van per kwartaal?","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"Ja, dat kun je aanvragen. Dat is handig als je vaak btw terugkrijgt, bijvoorbeeld in een jaar met grote investeringen. Je krijgt je geld dan sneller terug, maar je doet wel twaalf keer per jaar aangifte."},
{"id":"kennisbank/btw-aangifte-deadlines#27","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: Ik kan de btw niet betalen. Wat nu?","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"Doe altijd op tijd aangifte, ook als je niet kunt betalen. Een te late aangifte geeft een extra boete. Neem daarna contact op met de Belastingdienst over een betalingsregeling. Bij ons regelen we dit voor je. Je levert je bonnetjes en facturen aan uiterlijk de 10e na afloop van het kwartaal. Wij verwerken alles, laten je vooraf weten wat je moet betalen en dienen de aangifte op tijd in. Geschreven door Koen Avezaat en Daan Evers Boekhouders en oprichters van Avezaat & Evers. Dagelijks bezig met de administratie en aangiftes van zzp’ers. Over ons Dit artikel geeft algemene informatie. Voor je eigen situatie kun je het beste even contact met ons opnemen, of kijken op de website van de Belastingdienst."},
{"id":"kennisbank/btw-aangifte-deadlines#28","groep":"Kennisbank","titel":"Btw-aangifte als zzp’er: deadlines en hoe het werkt: Nooit meer een btw-deadline missen?","bron":"/kennisbank/btw-aangifte-deadlines","tags":"","tekst":"Wij doen je btw-aangifte elk kwartaal, inbegrepen in je pakket van €80 per maand. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"kennisbank/hoeveel-opzij-zetten-belasting#29","groep":"Kennisbank","titel":"Hoeveel moet je als zzp’er opzijzetten voor belasting?","bron":"/kennisbank/hoeveel-opzij-zetten-belasting","tags":"","tekst":"Home / Kennisbank / Belasting opzijzetten  Door Koen Avezaat en Daan Evers. Bijgewerkt in oktober 2026, 4 minuten lezen. Twee potjes: één voor de btw en één voor je inkomstenbelasting. Reken hieronder uit hoeveel je van elke betaling apart zet."},
{"id":"kennisbank/hoeveel-opzij-zetten-belasting#30","groep":"Kennisbank","titel":"Hoeveel moet je als zzp’er opzijzetten voor belasting?: Reken uit wat je opzijzet","bron":"/kennisbank/hoeveel-opzij-zetten-belasting","tags":"","tekst":"Vul je verwachte winst en een factuurbedrag in. Je ziet direct hoeveel je van die betaling apart zet. Indicatie voor een eenmanszaak zonder ander inkomen, jonger dan de AOW-leeftijd, zonder startersaftrek. We rekenen het percentage over het factuurbedrag, niet over je winst; daardoor houd je vanzelf een kleine buffer over. Heb je ook een baan in loondienst, dan zet je meer opzij. Aan deze berekening kun je geen rechten ontlenen. Als zzp’er krijg je je geld bruto binnen. Er zit btw in die niet van jou is, en over je winst betaal je later nog inkomstenbelasting en de bijdrage Zorgverzekeringswet (Zvw). Zet je daar niets voor apart, dan schrik je bij de aanslag. Je hebt twee potjes nodig."},
{"id":"kennisbank/hoeveel-opzij-zetten-belasting#31","groep":"Kennisbank","titel":"Hoeveel moet je als zzp’er opzijzetten voor belasting?: Potje 1: de btw","bron":"/kennisbank/hoeveel-opzij-zetten-belasting","tags":"","tekst":"De btw die je klant betaalt, draag je af aan de Belastingdienst. Zet daarom van elke betaling de btw direct apart. Stuur je een factuur van €1.000 plus €210 btw, dan zet je die €210 opzij. De btw die je zelf op kosten betaalt, trek je daar elk kwartaal weer van af. Het potje is dus meestal iets te vol, en dat is precies goed. Na je btw-aangifte haal je het restje eruit. Verleg je de btw, bijvoorbeeld in de bouw, of werk je btw-vrij in de zorg? Dan is er voor die omzet geen btw om opzij te zetten."},
{"id":"kennisbank/hoeveel-opzij-zetten-belasting#32","groep":"Kennisbank","titel":"Hoeveel moet je als zzp’er opzijzetten voor belasting?: Potje 2: inkomstenbelasting en Zvw","bron":"/kennisbank/hoeveel-opzij-zetten-belasting","tags":"","tekst":"Hoeveel je hiervoor nodig hebt, hangt af van je winst: je omzet min je zakelijke kosten. Dit betaal je in 2026 ongeveer, als je het urencriterium haalt en geen andere inkomsten hebt: Winst per jaar Belasting en Zvw Deel van je winst €20.000 €1.173 6% €30.000 €2.011 7% €40.000 €5.445 14% €50.000 €9.445 19% €60.000 €14.022 23% €75.000 €21.266 28% Berekend met de tarieven van 2026, inclusief zelfstandigenaftrek, mkb-winstvrijstelling, heffingskortingen en Zvw. Zonder startersaftrek, partner, hypotheek of andere inkomsten. Reken je eigen situatie uit met onze netto-inkomen-calculator ."},
{"id":"kennisbank/hoeveel-opzij-zetten-belasting#33","groep":"Kennisbank","titel":"Hoeveel moet je als zzp’er opzijzetten voor belasting?: Waarom het percentage zo snel stijgt","bron":"/kennisbank/hoeveel-opzij-zetten-belasting","tags":"","tekst":"Bij een lage winst valt de belasting mee, omdat je heffingskortingen veel wegstrepen. Boven ongeveer €40.000 worden die kortingen afgebouwd. Van elke euro die je dan extra verdient, gaat ongeveer 40 tot 48 cent naar belasting en Zvw. Groeit je bedrijf, dan moet je potje dus harder meegroeien dan je omzet."},
{"id":"kennisbank/hoeveel-opzij-zetten-belasting#34","groep":"Kennisbank","titel":"Hoeveel moet je als zzp’er opzijzetten voor belasting?: Wanneer je meer opzij zet","bron":"/kennisbank/hoeveel-opzij-zetten-belasting","tags":"","tekst":"Je hebt ook een baan in loondienst. Je heffingskortingen worden dan al via je loon gebruikt, en je winst komt bovenop je salaris. Reken dan al snel op 35 tot 45% van je winst. Je haalt het urencriterium niet. Dan krijg je geen zelfstandigenaftrek en betaal je over een hoger bedrag. Je winst schommelt sterk. Houd een extra buffer aan voor een rustig jaar. Ben je starter? Dan scheelt de startersaftrek in je eerste jaren. Zet toch het normale bedrag apart: wat over is, is je buffer."},
{"id":"kennisbank/hoeveel-opzij-zetten-belasting#35","groep":"Kennisbank","titel":"Hoeveel moet je als zzp’er opzijzetten voor belasting?: En je voorlopige aanslag?","bron":"/kennisbank/hoeveel-opzij-zetten-belasting","tags":"","tekst":"Betaal je elke maand een voorlopige aanslag die goed klopt met je winst, dan betaal je potje 2 eigenlijk al onderweg. Je hoeft dan alleen het verschil apart te zetten. Is je voorlopige aanslag te laag, dan groeit dat verschil snel. Lees hoe je hem aanpast."},
{"id":"kennisbank/hoeveel-opzij-zetten-belasting#36","groep":"Kennisbank","titel":"Hoeveel moet je als zzp’er opzijzetten voor belasting?: Zo houd je het simpel","bron":"/kennisbank/hoeveel-opzij-zetten-belasting","tags":"","tekst":"Open een aparte zakelijke spaarrekening, alleen voor belasting. Komt er een betaling binnen? Zet direct de btw en een vast percentage van het bedrag zonder btw over. Kies het percentage uit de tabel bij de winst die je verwacht, en rond naar boven af. Betaal je btw-aangifte en je voorlopige aanslag vanaf die rekening. Kijk elk kwartaal of het percentage nog past bij je winst. Voorbeeld: je verwacht €50.000 winst en houdt 20% aan. Je klant betaalt een factuur van €2.000 plus €420 btw. Je zet €420 + €400 = €820 apart. Omdat je over je omzet rekent en niet over je winst, houd je vanzelf een kleine buffer over."},
{"id":"kennisbank/hoeveel-opzij-zetten-belasting#37","groep":"Kennisbank","titel":"Hoeveel moet je als zzp’er opzijzetten voor belasting?: Waar zet ik het geld het beste neer?","bron":"/kennisbank/hoeveel-opzij-zetten-belasting","tags":"","tekst":"Op een aparte zakelijke spaarrekening die je niet voor iets anders gebruikt. Dan zie je in één oogopslag wat er beschikbaar is, en kom je niet in de verleiding om het uit te geven."},
{"id":"kennisbank/hoeveel-opzij-zetten-belasting#38","groep":"Kennisbank","titel":"Hoeveel moet je als zzp’er opzijzetten voor belasting?: Mag ik de btw tussentijds gebruiken?","bron":"/kennisbank/hoeveel-opzij-zetten-belasting","tags":"","tekst":"Liever niet. De btw is niet van jou en moet elk kwartaal betaald worden. Gebruik je het tussendoor, dan zit je bij de aangifte vaak krap."},
{"id":"kennisbank/hoeveel-opzij-zetten-belasting#39","groep":"Kennisbank","titel":"Hoeveel moet je als zzp’er opzijzetten voor belasting?: Ik heb te veel opzij gezet. Wat nu?","bron":"/kennisbank/hoeveel-opzij-zetten-belasting","tags":"","tekst":"Dan heb je een buffer, en dat is als ondernemer nooit verkeerd. Houd het aan voor een rustige periode, of overleg of het slim is om een deel in te leggen voor je pensioen."},
{"id":"kennisbank/hoeveel-opzij-zetten-belasting#40","groep":"Kennisbank","titel":"Hoeveel moet je als zzp’er opzijzetten voor belasting?: Zit de Zvw-bijdrage in de tabel?","bron":"/kennisbank/hoeveel-opzij-zetten-belasting","tags":"","tekst":"Ja. De bijdrage Zorgverzekeringswet is in 2026 4,85% van je inkomen tot een maximum, en die staat in de bedragen in de tabel. Bij ons: je vaste boekhouder loopt dit elk jaar met je door, ruim voor de jaarwisseling. Vragen stellen is altijd inbegrepen. Geschreven door Koen Avezaat en Daan Evers Boekhouders en oprichters van Avezaat & Evers. Dagelijks bezig met de administratie en aangiftes van zzp’ers. Over ons Dit artikel geeft algemene informatie. Voor je eigen situatie kun je het beste even contact met ons opnemen, of kijken op de website van de Belastingdienst."},
{"id":"kennisbank/hoeveel-opzij-zetten-belasting#41","groep":"Kennisbank","titel":"Hoeveel moet je als zzp’er opzijzetten voor belasting?: Nooit meer schrikken van een aanslag","bron":"/kennisbank/hoeveel-opzij-zetten-belasting","tags":"","tekst":"Wij houden bij hoeveel je opzij moet zetten en passen je voorlopige aanslag aan als je meer verdient. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"kennisbank/investeren-voor-jaareinde#42","groep":"Kennisbank","titel":"Investeren vóór de jaarwisseling: levert het je wat op?","bron":"/kennisbank/investeren-voor-jaareinde","tags":"","tekst":"Home / Kennisbank / Investeren vóór de jaarwisseling  Door Koen Avezaat en Daan Evers. Bijgewerkt in oktober 2026, 4 minuten lezen. In december hoor je het vaak: \"Koop nog snel iets, dan betaal je minder belasting.\" Dat klopt soms, maar lang niet altijd. Hier lees je hoe de investeringsaftrek werkt en wanneer het je echt iets oplevert."},
{"id":"kennisbank/investeren-voor-jaareinde#43","groep":"Kennisbank","titel":"Investeren vóór de jaarwisseling: levert het je wat op?: Hoe werkt de KIA?","bron":"/kennisbank/investeren-voor-jaareinde","tags":"","tekst":"Investeer je in bedrijfsmiddelen, zoals een bus, machines, gereedschap of een laptop, dan krijg je bovenop de gewone afschrijving een extra aftrek: de kleinschaligheidsinvesteringsaftrek (KIA). Hoe hoog die is, hangt af van wat je in totaal in een jaar investeert. Totaal geïnvesteerd in 2026 KIA Tot en met €2.900 Geen aftrek €2.901 tot en met €71.683 28% van het bedrag €71.684 tot en met €132.746 €20.072 €132.747 tot en met €398.236 €20.072 min 7,56% van het bedrag boven €132.746 Meer dan €398.236 Geen aftrek Een bedrijfsmiddel telt alleen mee als het minstens €450 kost (excl. btw). Een gewone personenauto, grond en je eigen woning tellen niet mee. Een bestelauto wel."},
{"id":"kennisbank/investeren-voor-jaareinde#44","groep":"Kennisbank","titel":"Investeren vóór de jaarwisseling: levert het je wat op?: Wat levert het je echt op?","bron":"/kennisbank/investeren-voor-jaareinde","tags":"","tekst":"De KIA is een aftrek van je winst, geen korting op je aankoop. Je bespaart dus belasting over het bedrag van de aftrek, niet het hele bedrag. Investering in een bestelbus (excl. btw) €20.000 KIA (28%) €5.600 extra aftrek Na mkb-winstvrijstelling (12,7%) €4.889 lagere belastbare winst Belastingvoordeel bij 37,56% ongeveer €1.840 Daarnaast schrijf je de bus gewoon af, wat elk jaar je winst verlaagt. De btw op de aankoop vraag je terug in je btw-aangifte. Maar onthoud: je geeft €20.000 uit om €1.840 extra voordeel te krijgen. Koop dus alleen wat je echt nodig hebt."},
{"id":"kennisbank/investeren-voor-jaareinde#45","groep":"Kennisbank","titel":"Investeren vóór de jaarwisseling: levert het je wat op?: Wanneer is investeren vóór 31 december slim?","bron":"/kennisbank/investeren-voor-jaareinde","tags":"","tekst":"Je zit net onder de drempel. Heb je dit jaar €2.500 geïnvesteerd en wilde je in januari een laptop van €1.200 kopen? Koop je hem in december, dan kom je op €3.700 en krijg je €1.036 KIA. In januari krijg je voor die laptop alleen niets, tenzij je in 2027 ook boven de drempel komt. Je hebt een goed jaar. Hoe hoger je winst, hoe meer belasting je bespaart met elke euro aftrek."},
{"id":"kennisbank/investeren-voor-jaareinde#46","groep":"Kennisbank","titel":"Investeren vóór de jaarwisseling: levert het je wat op?: Wanneer juist niet?","bron":"/kennisbank/investeren-voor-jaareinde","tags":"","tekst":"Je zit al boven €71.683. Dan levert extra investeren dit jaar geen extra KIA op. Doorschuiven naar januari kan dan beter zijn. Je hebt het geld eigenlijk niet. Een aankoop op krediet voor een paar honderd euro belastingvoordeel is zelden verstandig. Je verkoopt het snel weer. Verkoop je een bedrijfsmiddel binnen vijf jaar, dan kan een deel van de aftrek terugkomen. Dat heet de desinvesteringsbijtelling."},
{"id":"kennisbank/investeren-voor-jaareinde#47","groep":"Kennisbank","titel":"Investeren vóór de jaarwisseling: levert het je wat op?: Bestellen in december, leveren in januari?","bron":"/kennisbank/investeren-voor-jaareinde","tags":"","tekst":"De KIA telt in het jaar waarin je de koop sluit, dus wanneer je bestelt. Het deel dat je nog niet hebt betaald, telt pas mee als je het betaalt of als je het bedrijfsmiddel in gebruik neemt. Bestel je in december en betaal je bij levering in januari, dan schuift de aftrek dus (deels) naar het volgende jaar."},
{"id":"kennisbank/investeren-voor-jaareinde#48","groep":"Kennisbank","titel":"Investeren vóór de jaarwisseling: levert het je wat op?: Afschrijven: hoe werkt dat?","bron":"/kennisbank/investeren-voor-jaareinde","tags":"","tekst":"Een bedrijfsmiddel dat je meerdere jaren gebruikt, boek je niet in één keer als kosten. Je verdeelt de aankoopprijs over de jaren dat je het gebruikt. Per jaar mag je maximaal 20% van de aanschafprijs afschrijven. Kost iets minder dan €450, dan mag je het wel direct als kosten boeken. Aanschafprijs bestelbus (excl. btw) €20.000 Verwachte restwaarde na 5 jaar €4.000 Af te schrijven €16.000 Afschrijving per jaar €3.200 KIA in het jaar van aankoop €5.600 (eenmalig) De afschrijving verlaagt vijf jaar lang je winst. De KIA komt daar in het eerste jaar eenmalig bovenop."},
{"id":"kennisbank/investeren-voor-jaareinde#49","groep":"Kennisbank","titel":"Investeren vóór de jaarwisseling: levert het je wat op?: Wat telt wel en niet mee voor de KIA?","bron":"/kennisbank/investeren-voor-jaareinde","tags":"","tekst":"Telt wel mee: een bestelauto, machines, gereedschap, een laptop of computer, kantoormeubilair en inventaris van je werkplaats of zaak, mits elk bedrijfsmiddel minstens €450 kost. Telt niet mee: een gewone personenauto, grond, je eigen woning, en spullen onder de €450 per stuk."},
{"id":"kennisbank/investeren-voor-jaareinde#50","groep":"Kennisbank","titel":"Investeren vóór de jaarwisseling: levert het je wat op?: Telt een tweedehands aankoop mee?","bron":"/kennisbank/investeren-voor-jaareinde","tags":"","tekst":"Ja, ook tweedehands bedrijfsmiddelen tellen mee voor de KIA, mits ze minstens €450 kosten."},
{"id":"kennisbank/investeren-voor-jaareinde#51","groep":"Kennisbank","titel":"Investeren vóór de jaarwisseling: levert het je wat op?: Telt de btw mee in het investeringsbedrag?","bron":"/kennisbank/investeren-voor-jaareinde","tags":"","tekst":"Ben je btw-plichtig, dan rekenen we met het bedrag zonder btw. De btw vraag je apart terug in je btw-aangifte."},
{"id":"kennisbank/investeren-voor-jaareinde#52","groep":"Kennisbank","titel":"Investeren vóór de jaarwisseling: levert het je wat op?: En als ik lease?","bron":"/kennisbank/investeren-voor-jaareinde","tags":"","tekst":"Bij financial lease word je economisch eigenaar en kun je meestal wel KIA krijgen. Bij operational lease huur je het bedrijfsmiddel en betaal je een maandbedrag dat gewoon kosten is. Dan krijg je geen KIA. Bij ons: je vaste boekhouder loopt dit elk jaar met je door, ruim voor de jaarwisseling. Vragen stellen is altijd inbegrepen. Geschreven door Koen Avezaat en Daan Evers Boekhouders en oprichters van Avezaat & Evers. Dagelijks bezig met de administratie en aangiftes van zzp’ers. Over ons Dit artikel geeft algemene informatie. Voor je eigen situatie kun je het beste even contact met ons opnemen, of kijken op de website van de Belastingdienst."},
{"id":"kennisbank/investeren-voor-jaareinde#53","groep":"Kennisbank","titel":"Investeren vóór de jaarwisseling: levert het je wat op?: Twijfel je over een aankoop?","bron":"/kennisbank/investeren-voor-jaareinde","tags":"","tekst":"Wij rekenen met je uit wat het oplevert, vóór je koopt. Altijd inbegrepen bij je abonnement. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"kennisbank/jaareinde-checklist-zzp#54","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Home / Kennisbank / Jaareinde-checklist  Door Koen Avezaat en Daan Evers. Bijgewerkt in oktober 2026, 4 minuten lezen. De laatste weken van het jaar bepalen voor een groot deel hoeveel belasting je over 2026 betaalt. Een aantal zaken kun je na 31 december niet meer veranderen. Loop deze lijst daarom in november of begin december door."},
{"id":"kennisbank/jaareinde-checklist-zzp#55","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: 1. Check of je het urencriterium haalt","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Voor de zelfstandigenaftrek van €1.200 (2026) en de startersaftrek moet je minstens 1.225 uur per jaar aan je bedrijf besteden. Ook uren voor administratie, acquisitie en reizen tellen mee. Tel je uren nu op. Zit je er net onder, dan weet je hoeveel uur je nog nodig hebt. Zonder urenregistratie kun je het bij een controle niet bewijzen. Lees meer over het urencriterium ."},
{"id":"kennisbank/jaareinde-checklist-zzp#56","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: 2. Plan je investeringen","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Investeer je in een jaar tussen €2.901 en €71.683 in bedrijfsmiddelen, dan krijg je 28% kleinschaligheidsinvesteringsaftrek (KIA). Zit je net onder de drempel en wilde je toch al iets kopen? Dan kan het slim zijn dat nog dit jaar te doen. Andersom: heb je al veel geïnvesteerd, dan kan een aankoop doorschuiven naar januari soms meer opleveren. Lees wanneer investeren loont ."},
{"id":"kennisbank/jaareinde-checklist-zzp#57","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: 3. Boek oninbare facturen af","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Heb je facturen die niet meer betaald gaan worden, bijvoorbeeld door een faillissement? Dan kun je ze afboeken, waardoor je winst lager wordt. De btw die je al hebt afgedragen, vraag je terug zodra de factuur oninbaar is, en uiterlijk één jaar na de uiterste betaaldatum."},
{"id":"kennisbank/jaareinde-checklist-zzp#58","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: 4. Tel je voorraad","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Verkoop je producten? Dan is je inkoop pas kosten op het moment dat je het product verkoopt. Wat op 31 december nog op de plank ligt, telt dus nog niet als kosten voor dit jaar. Tel daarom je voorraad, tegen de inkoopprijs. Een voorbeeld: je koopt in 2026 voor €10.000 aan producten in, en op 31 december ligt er nog voor €3.000 op voorraad. Je kosten voor 2026 zijn dan €7.000, niet €10.000. Die €3.000 worden kosten in 2027, als je die producten verkoopt. Tel je te weinig voorraad, dan komt je winst dit jaar te laag uit en volgend jaar te hoog. Tel je te veel, dan andersom."},
{"id":"kennisbank/jaareinde-checklist-zzp#59","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: 5. Leg onderhanden werk vast","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Ben je met een opdracht bezig die je pas in januari factureert? Het werk dat je al in 2026 hebt gedaan, hoort bij je winst van 2026. Schrijf op hoeveel uur en materiaal er al in zit. Zet alle deadlines in je agenda Btw-aangifte, aangifte inkomstenbelasting, KOR en jaareinde. Je krijgt een week van tevoren een herinnering, en de agenda werkt zich vanzelf bij. Gratis. iPhone of Mac Google Agenda Outlook Download"},
{"id":"kennisbank/jaareinde-checklist-zzp#60","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: 6. Kosten vooruitbetalen? Meestal geen zin","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Een veelgehoorde tip is om kosten nog snel in december te betalen. Dat werkt meestal niet. Kosten tellen in het jaar waar ze bij horen. Betaal je in december de huur of een abonnement voor heel 2027, dan zijn dat kosten van 2027. Alleen kosten die echt in 2026 horen, zoals een cursus die je in december volgt, verlagen je winst van dit jaar."},
{"id":"kennisbank/jaareinde-checklist-zzp#61","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: 7. Controleer je privégebruik","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Gebruik je een bestelauto of andere spullen van de zaak ook privé? Kijk of je rittenregistratie compleet is. Rijd je met een auto van de zaak niet meer dan 500 kilometer per jaar privé, dan betaal je geen bijtelling. Dat moet je wel kunnen aantonen, en een sluitende rittenregistratie is daarvoor de beste manier."},
{"id":"kennisbank/jaareinde-checklist-zzp#62","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: 8. Pas je voorlopige aanslag aan","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Verdien je dit jaar meer dan de Belastingdienst denkt? Pas je voorlopige aanslag dan aan, zodat je geen grote naheffing krijgt. Dien je de aangifte of een aangepaste voorlopige aanslag over 2026 vóór 1 mei 2027 in, dan voorkom je belastingrente. Lees hoe de voorlopige aanslag werkt ."},
{"id":"kennisbank/jaareinde-checklist-zzp#63","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: 9. Overweeg sparen voor je pensioen","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Als zzp’er bouw je zelf pensioen op. Binnen je jaarruimte mag je inleg in een lijfrenteproduct aftrekken van je inkomen. Wat je vóór 31 december inlegt, telt mee voor 2026. Hoe groot je jaarruimte is, hangt af van je inkomen. Wij rekenen het voor je uit."},
{"id":"kennisbank/jaareinde-checklist-zzp#64","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: 10. Maak je administratie compleet","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Lever alle bonnetjes en facturen van het vierde kwartaal aan. De btw-aangifte over oktober tot en met december moet uiterlijk 31 januari binnen zijn, en een complete administratie maakt ook de jaarcijfers en je aangifte inkomstenbelasting eenvoudiger."},
{"id":"kennisbank/jaareinde-checklist-zzp#65","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: Ga je per 1 januari met de KOR werken?","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Heb je een omzet van maximaal €20.000 per jaar, dan kun je kiezen voor de kleineondernemersregeling (KOR). Je rekent dan geen btw en doet geen btw-aangifte, maar je kunt ook geen btw terugvragen. Wil je per 1 januari beginnen, meld je dan op tijd aan bij de Belastingdienst: minimaal vier weken voor de ingangsdatum. Of het voor jou gunstig is, hangt af van je klanten en je investeringen. Werk je vooral voor bedrijven, dan levert de KOR vaak weinig op. Lees wanneer de KOR loont."},
{"id":"kennisbank/jaareinde-checklist-zzp#66","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: Ik haal het urencriterium net niet. Wat mis ik?","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"De zelfstandigenaftrek (€1.200 in 2026) en, als je starter bent, de startersaftrek. De mkb-winstvrijstelling krijg je wel, daar is geen urencriterium voor nodig."},
{"id":"kennisbank/jaareinde-checklist-zzp#67","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: Moet ik in december iets doen voor de btw?","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Niet direct. De aangifte over het vierde kwartaal moet uiterlijk 31 januari binnen zijn. Lever je bonnetjes en facturen van oktober tot en met december dus begin januari aan. Check wel of er facturen zijn die niet meer betaald worden: die btw kun je terugvragen."},
{"id":"kennisbank/jaareinde-checklist-zzp#68","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: Heeft het zin om in december nog extra te factureren of juist niet?","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Een factuur telt mee in het jaar van de factuurdatum. Doorschuiven naar januari verschuift de winst alleen naar volgend jaar en levert meestal weinig op, omdat je dan in dat jaar meer betaalt. Factureer wanneer het werk klaar is. Bij ons: je vaste boekhouder loopt dit elk jaar met je door, ruim voor de jaarwisseling. Vragen stellen is altijd inbegrepen. Geschreven door Koen Avezaat en Daan Evers Boekhouders en oprichters van Avezaat & Evers. Dagelijks bezig met de administratie en aangiftes van zzp’ers. Over ons Dit artikel geeft algemene informatie. Voor je eigen situatie kun je het beste even contact met ons opnemen, of kijken op de website van de Belastingdienst."},
{"id":"kennisbank/jaareinde-checklist-zzp#69","groep":"Kennisbank","titel":"Jaareinde-checklist voor zzp’ers: 10 punten om vóór 31 december te regelen: Klaar voor het nieuwe jaar?","bron":"/kennisbank/jaareinde-checklist-zzp","tags":"","tekst":"Wij lopen je jaareinde met je door en doen je aangiftes. Voor €80 per maand. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"kennisbank/kleineondernemersregeling-kor#70","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Home / Kennisbank / KOR  Door Koen Avezaat en Daan Evers. Bijgewerkt in oktober 2026, 5 minuten lezen. Geen btw rekenen en geen btw-aangifte. Doe hieronder de KOR-check en zie in een minuut of het jou geld oplevert."},
{"id":"kennisbank/kleineondernemersregeling-kor#71","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Doe de KOR-check","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Vul je cijfers in en zie direct of de KOR je geld oplevert of kost. Duurt een minuut. Indicatie per jaar. Uitgangspunt: particulieren betalen met de KOR dezelfde prijs als nu (inclusief btw), bedrijven dezelfde prijs als nu (exclusief btw), en op je kosten zit 21% btw. Je omzet van dit jaar en vorig jaar moet allebei onder de € 20.000 blijven. Aan deze berekening kun je geen rechten ontlenen. Met de kleineondernemersregeling (KOR) reken je geen btw aan je klanten en doe je geen btw-aangifte. Dat klinkt als pure winst, maar dat is het niet altijd. Je kunt dan namelijk ook geen btw meer terugvragen op je kosten en investeringen. Of de KOR voor jou gunstig is, hangt vooral af van wie je klanten zijn."},
{"id":"kennisbank/kleineondernemersregeling-kor#72","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Hoe werkt de KOR?","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Je omzet is maximaal €20.000 per kalenderjaar . Dat geldt voor het jaar waarin je je aanmeldt én voor het jaar daarvoor. Je zet geen btw op je facturen en doet geen btw-aangifte. Je kunt geen btw terugvragen op je kosten en investeringen. Die btw wordt gewoon een kostenpost. De KOR geldt alleen voor de btw. Je boekhouding en je aangifte inkomstenbelasting blijven gewoon nodig."},
{"id":"kennisbank/kleineondernemersregeling-kor#73","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Wat telt mee als omzet?","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Alles wat je in Nederland aan klanten in rekening brengt voor leveringen en diensten waar btw op zit, ook als je de btw naar je opdrachtgever verlegt. Voordat je meedoet, reken je met bedragen zonder btw. Zit je eenmaal in de KOR, dan telt het hele bedrag dat je factureert. Niet mee tellen onder andere de verkoop van je eigen bedrijfsmiddelen, zoals je oude bus, en omzet die is vrijgesteld van btw, zoals medische zorg."},
{"id":"kennisbank/kleineondernemersregeling-kor#74","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Rekenvoorbeeld: particulieren of bedrijven?","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Twee zzp’ers met allebei €15.000 omzet per jaar en €2.000 aan kosten, waarover ze €420 btw hebben betaald (21%). Zonder KOR Met KOR Klanten zijn particulieren (zij betalen €15.000, inclusief eventuele btw) Wat je overhoudt €10.397 €12.580 Verschil €2.183 meer Klanten zijn bedrijven (zij betalen €15.000 plus btw, die ze zelf terugvragen) Wat je overhoudt €13.000 €12.580 Verschil €420 minder Werk je voor particulieren, dan is de btw voor hen een echte kostenpost. Met de KOR kun je dezelfde prijs vragen en houd je meer over, of kun je goedkoper zijn dan je concurrent. Werk je voor bedrijven, dan levert de KOR je niets op: zij trekken de btw toch af, en jij verliest de btw op je eigen kosten."},
{"id":"kennisbank/kleineondernemersregeling-kor#75","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Wanneer is de KOR slim, en wanneer niet?","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Vaak slim Je werkt vooral voor particulieren, bijvoorbeeld als kapper, fotograaf, coach of klusser. Je omzet blijft ruim onder de €20.000, bijvoorbeeld omdat je naast een baan onderneemt. Je hebt weinig kosten en investeringen. Vaak niet slim Je werkt vooral voor bedrijven, of je werkt in de bouw met verlegde btw. Je gaat flink investeren, bijvoorbeeld in een bus of machines. Je verwacht binnenkort boven de €20.000 uit te komen."},
{"id":"kennisbank/kleineondernemersregeling-kor#76","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Let op met investeringen: herziening","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Heb je de afgelopen jaren btw teruggevraagd op een duurder bedrijfsmiddel, zoals een bus of machine? Dan moet je bij het instappen in de KOR mogelijk een deel van die btw terugbetalen. Dat heet herziening. Voor roerende zaken loopt die periode tot en met vier jaar na het jaar waarin je ze in gebruik nam. Bij een recente grote aankoop rekenen we dit eerst voor je uit."},
{"id":"kennisbank/kleineondernemersregeling-kor#77","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Aanmelden per 1 januari 2027","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Je meldt je aan via Mijn Belastingdienst Zakelijk. Je aanmelding moet uiterlijk vier weken voor de ingangsdatum binnen zijn, en de KOR gaat in aan het begin van een aangifteperiode. Wil je per 1 januari 2027 meedoen, meld je dan uiterlijk begin december 2026 aan. Wij houden 3 december aan, zodat je zeker op tijd bent."},
{"id":"kennisbank/kleineondernemersregeling-kor#78","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Wat als je over de €20.000 gaat?","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Dan stopt de KOR direct. Over de factuur waarmee je over de grens gaat, reken je al gewoon btw, over het hele bedrag. Vanaf dat moment doe je weer btw-aangifte. Houd je omzet dus goed bij als je in de buurt van de grens komt."},
{"id":"kennisbank/kleineondernemersregeling-kor#79","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Stoppen met de KOR","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Wil je zelf stoppen, bijvoorbeeld omdat je gaat investeren of meer voor bedrijven gaat werken? Meld je dan uiterlijk vier weken voor het begin van een nieuwe aangifteperiode af. Daarna kun je de rest van dat jaar en het hele volgende kalenderjaar niet opnieuw meedoen."},
{"id":"kennisbank/kleineondernemersregeling-kor#80","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Je facturen met de KOR","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Je zet geen btw-tarief en geen btw-bedrag op je factuur. Zet er voor de duidelijkheid bij dat je gebruikmaakt van de kleineondernemersregeling, zodat je klant snapt waarom er geen btw op staat. Je boekhouding en je bonnetjes bewaar je gewoon zeven jaar, net als anders."},
{"id":"kennisbank/kleineondernemersregeling-kor#81","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Moet ik met de KOR nog een boekhouding bijhouden?","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Ja. Je hoeft geen btw-administratie meer te voeren, maar voor je aangifte inkomstenbelasting heb je nog steeds een boekhouding nodig. Je facturen en bonnetjes bewaar je zeven jaar."},
{"id":"kennisbank/kleineondernemersregeling-kor#82","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Ik ben zorgverlener en al vrijgesteld van btw. Heb ik de KOR nodig?","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Voor je vrijgestelde zorg niet: daar reken je al geen btw over, en die omzet telt niet mee voor de grens. De KOR kan wel interessant zijn als je daarnaast btw-belaste diensten levert, zoals coaching of de verkoop van producten."},
{"id":"kennisbank/kleineondernemersregeling-kor#83","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Kan ik halverwege het jaar instappen?","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Ja, de KOR kan ingaan aan het begin van een aangifteperiode, meestal een kwartaal. Je aanmelding moet dan uiterlijk vier weken van tevoren binnen zijn. Je omzet van dat hele jaar moet onder de €20.000 blijven."},
{"id":"kennisbank/kleineondernemersregeling-kor#84","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Ik verkoop ook in andere EU-landen. Kan ik de KOR gebruiken?","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Voor je Nederlandse omzet wel. Sinds 2025 bestaat er ook een EU-KOR voor ondernemers die in meerdere EU-landen verkopen, met een totale EU-omzet tot €100.000. Daar gelden extra voorwaarden en een kwartaalopgave. Bij ons: je vaste boekhouder loopt dit elk jaar met je door, ruim voor de jaarwisseling. Vragen stellen is altijd inbegrepen. Geschreven door Koen Avezaat en Daan Evers Boekhouders en oprichters van Avezaat & Evers. Dagelijks bezig met de administratie en aangiftes van zzp’ers. Over ons Dit artikel geeft algemene informatie. Voor je eigen situatie kun je het beste even contact met ons opnemen, of kijken op de website van de Belastingdienst."},
{"id":"kennisbank/kleineondernemersregeling-kor#85","groep":"Kennisbank","titel":"Kleineondernemersregeling (KOR): wel of niet doen als zzp’er?: Twijfel je over de KOR?","bron":"/kennisbank/kleineondernemersregeling-kor","tags":"","tekst":"Wij rekenen voor je uit of het voor jou loont, en melden je op tijd aan. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"kennisbank/mkb-pakket-2026#86","groep":"Kennisbank","titel":"Mkb-pakket aangekondigd: wat betekent het voor zzp’ers?","bron":"/kennisbank/mkb-pakket-2026","tags":"","tekst":"Home / Kennisbank / Mkb-pakket  Door Koen Avezaat en Daan Evers. Gepubliceerd op 17 november 2026 , 2 minuten lezen. Momentopname. Dit bericht is geschreven op 17 november 2026, op de dag van de aankondiging. De plannen zijn nog niet uitgewerkt. Zodra er meer bekend is, werken we deze pagina bij. Het kabinet-Jetten (D66, VVD, CDA) heeft op 17 november 2026, na een coalitiecrisis, een mkb-pakket aangekondigd. Volgens premier Jetten moet het pakket ondernemers ondersteunen bij investeren, innoveren en verduurzamen. MKB-Nederland en VNO-NCW noemen het een “blijk van waardering”."},
{"id":"kennisbank/mkb-pakket-2026#87","groep":"Kennisbank","titel":"Mkb-pakket aangekondigd: wat betekent het voor zzp’ers?: Wat staat er al vast?","bron":"/kennisbank/mkb-pakket-2026","tags":"","tekst":"Het kabinet noemt drie concrete punten: De MKB-winstvrijstelling wordt verruimd. De Milieu-investeringsaftrek (MIA) wordt verhoogd. Er komt extra inzet op verduurzaming ."},
{"id":"kennisbank/mkb-pakket-2026#88","groep":"Kennisbank","titel":"Mkb-pakket aangekondigd: wat betekent het voor zzp’ers?: Wat betekent de MKB-winstvrijstelling voor jou?","bron":"/kennisbank/mkb-pakket-2026","tags":"","tekst":"Ben je ondernemer voor de inkomstenbelasting, zoals de meeste zzp’ers en eenmanszaken? Dan betaal je over een deel van je winst geen belasting: dat deel is de MKB-winstvrijstelling. Je hoeft er niets voor aan te vragen, want hij wordt automatisch meegenomen in je aangifte. Anders dan bij de zelfstandigenaftrek geldt er geen urencriterium. Wordt de vrijstelling verruimd, dan valt straks een groter deel van je winst buiten de belasting. Hoeveel groter, is nog niet bekend."},
{"id":"kennisbank/mkb-pakket-2026#89","groep":"Kennisbank","titel":"Mkb-pakket aangekondigd: wat betekent het voor zzp’ers?: Wat is nog onbekend?","bron":"/kennisbank/mkb-pakket-2026","tags":"","tekst":"Er zijn nog geen percentages, bedragen of ingangsdatum. Een taskforce werkt de plannen uit. De uitwerking volgt in het voorjaar van 2027 en wordt budgettair verwerkt in de Voorjaarsnota. Het Belastingplan 2027 is op 12 november 2026 al door de Tweede Kamer aangenomen, en dit pakket zit daar niet in. We verwachten daarom niet dat je er in 2027 al iets van merkt. Zeker weten we dat pas als de uitwerking er ligt."},
{"id":"kennisbank/mkb-pakket-2026#90","groep":"Kennisbank","titel":"Mkb-pakket aangekondigd: wat betekent het voor zzp’ers?: Moet je nu iets doen?","bron":"/kennisbank/mkb-pakket-2026","tags":"","tekst":"Nee. Er verandert op dit moment niets aan je administratie of je aangifte. Je hoeft geen investeringen naar voren te halen of uit te stellen vanwege dit nieuws."},
{"id":"kennisbank/mkb-pakket-2026#91","groep":"Kennisbank","titel":"Mkb-pakket aangekondigd: wat betekent het voor zzp’ers?: We houden je op de hoogte","bron":"/kennisbank/mkb-pakket-2026","tags":"","tekst":"Zodra er concrete bedragen en data zijn, lees je hier wat het voor jou betekent. Vragen over je eigen situatie? Bel, app of mail je vaste boekhouder, of neem contact met ons op . Geschreven door Koen Avezaat en Daan Evers Boekhouders en oprichters van Avezaat & Evers. Dagelijks bezig met de administratie en aangiftes van zzp’ers. Over ons Bronnen: NOS en ANP, 17 november 2026. Dit bericht geeft de stand van zaken op 17 november 2026 weer. Voor je eigen situatie kun je het beste even contact met ons opnemen."},
{"id":"kennisbank/mkb-pakket-2026#92","groep":"Kennisbank","titel":"Mkb-pakket aangekondigd: wat betekent het voor zzp’ers?: Geen nieuws missen dat jou raakt?","bron":"/kennisbank/mkb-pakket-2026","tags":"","tekst":"Als je vaste boekhouder houden we wetswijzigingen voor je bij en vertellen we wat ze voor jou betekenen. Inbegrepen in je pakket van €80 per maand. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"kennisbank/netto-inkomen-berekenen#93","groep":"Kennisbank","titel":"Wat houd je netto over als zzp’er?","bron":"/kennisbank/netto-inkomen-berekenen","tags":"","tekst":"Home / Kennisbank / Netto-inkomen berekenen  Vul je omzet en kosten in en zie direct wat je na inkomstenbelasting en zorgverzekeringswet overhoudt, en hoeveel je opzij moet zetten. Indicatie voor een eenmanszaak zonder ander inkomen, jonger dan de AOW-leeftijd. Geen rekening gehouden met loon uit loondienst, een fiscale partner, eigen woning, toeslagen, pensioenopbouw of box 3. De tarieven voor 2027 zijn voorlopig: ze komen uit het Belastingplan 2027 en kunnen nog veranderen. Aan deze berekening kun je geen rechten ontlenen."},
{"id":"kennisbank/netto-inkomen-berekenen#94","groep":"Kennisbank","titel":"Wat houd je netto over als zzp’er?: Zo wordt het berekend","bron":"/kennisbank/netto-inkomen-berekenen","tags":"","tekst":"Winst: je omzet min je zakelijke kosten, allebei zonder btw. De btw die je ontvangt is niet van jou; die draag je af. Ondernemersaftrek: haal je het urencriterium, dan krijg je de zelfstandigenaftrek (€1.200 in 2026, €900 in 2027). In je eerste drie jaar als ondernemer komt daar de startersaftrek bij (€2.123 in 2026, €10 in 2027; vanaf 2028 vervalt die). Die krijg je alleen als je in de vijf jaar vóór dat jaar niet of maximaal twee keer zelfstandigenaftrek hebt gehad. Was je eerder al ondernemer, dan heb je er dus vaak geen recht op. Alles over de voorwaarden lees je in ons artikel over de zelfstandigenaftrek en het urencriterium . Mkb-winstvrijstelling: over 12,7% van je winst na ondernemersaftrek betaal je geen belasting. Hier heb je geen urencriterium voor nodig. Inkomstenbelasting: over wat overblijft betaal je belasting in schijven."},
{"id":"kennisbank/netto-inkomen-berekenen#95","groep":"Kennisbank","titel":"Wat houd je netto over als zzp’er?: Zo wordt het berekend","bron":"/kennisbank/netto-inkomen-berekenen","tags":"","tekst":"Daar gaan de algemene heffingskorting en de arbeidskorting nog vanaf. Zorgverzekeringswet: als ondernemer betaal je zelf een inkomensafhankelijke bijdrage (4,85% in 2026). Die komt op een aparte aanslag. Dit staat los van je zorgpremie bij je verzekeraar."},
{"id":"kennisbank/netto-inkomen-berekenen#96","groep":"Kennisbank","titel":"Wat houd je netto over als zzp’er?: Rekenvoorbeeld: €60.000 omzet","bron":"/kennisbank/netto-inkomen-berekenen","tags":"","tekst":"Een zzp’er met €60.000 omzet en €10.000 kosten in 2026, die het urencriterium haalt, geen startersaftrek meer heeft en verder geen inkomen heeft: Winst (omzet min kosten) €50.000 Zelfstandigenaftrek – €1.200 Mkb-winstvrijstelling (12,7%) – €6.198 Belastbaar inkomen €42.602 Inkomstenbelasting vóór kortingen €15.298 Algemene heffingskorting en arbeidskorting – €7.919 Te betalen inkomstenbelasting €7.379 Bijdrage Zorgverzekeringswet (4,85%) €2.066 Netto over €40.555 Van de €50.000 winst gaat in dit voorbeeld dus €9.445 naar de Belastingdienst: 19%. Dat is minder dan veel mensen denken. De heffingskortingen en de ondernemersaftrek doen veel."},
{"id":"kennisbank/netto-inkomen-berekenen#97","groep":"Kennisbank","titel":"Wat houd je netto over als zzp’er?: Hoeveel moet je opzij zetten?","bron":"/kennisbank/netto-inkomen-berekenen","tags":"","tekst":"Het percentage stijgt snel naarmate je meer verdient, omdat de heffingskortingen dan afnemen. Indicatie voor 2026, met urencriterium, zonder startersaftrek en zonder ander inkomen: Winst per jaar Belasting en Zvw Opzij zetten €20.000 €1.173 6% €30.000 €2.010 7% €40.000 €5.445 14% €50.000 €9.445 19% €60.000 €14.022 23% €80.000 €23.680 30% Haal je het urencriterium niet, dan mis je de zelfstandigenaftrek. Bij €50.000 winst betaal je dan ongeveer €500 meer. Zet daarnaast altijd de btw apart: die zit niet in deze bedragen."},
{"id":"kennisbank/netto-inkomen-berekenen#98","groep":"Kennisbank","titel":"Wat houd je netto over als zzp’er?: Wat zit er niet in deze berekening?","bron":"/kennisbank/netto-inkomen-berekenen","tags":"","tekst":"Ander inkomen , zoals een baan in loondienst naast je bedrijf. Dan val je eerder in een hogere schijf en krijg je minder heffingskorting. Een fiscaal partner , hypotheekrenteaftrek en vermogen in box 3. Pensioeninleg in een lijfrente, die je inkomen verlaagt. Toeslagen , zoals zorgtoeslag. Een hogere winst kan je toeslag verlagen. Voor een precieze berekening van jouw situatie kijken we naar al deze onderdelen samen."},
{"id":"kennisbank/netto-inkomen-berekenen#99","groep":"Kennisbank","titel":"Wat houd je netto over als zzp’er?: Waarom opzij zetten zo belangrijk is","bron":"/kennisbank/netto-inkomen-berekenen","tags":"","tekst":"Als zzp’er houdt niemand belasting voor je in. Je krijgt pas achteraf een aanslag, soms anderhalf jaar later. Wie dat geld al heeft uitgegeven, komt in de problemen. Zet daarom elke maand het bedrag hierboven apart op een spaarrekening, en vraag een voorlopige aanslag aan. Dan betaal je in maandelijkse termijnen en is er achteraf geen verrassing. Bij ons: in je maandelijkse gesprek kijken we samen naar je cijfers tot nu toe en wat je opzij moet zetten. We passen je voorlopige aanslag aan als je meer of minder verdient dan verwacht. Geschreven door Koen Avezaat en Daan Evers Boekhouders en oprichters van Avezaat & Evers. Dagelijks bezig met de administratie en aangiftes van zzp’ers. Over ons Bronnen: Belastingplan 2026 en 2027 (Prinsjesdag 2026), Belastingdienst. Laatst bijgewerkt: oktober 2026."},
{"id":"kennisbank/netto-inkomen-berekenen#100","groep":"Kennisbank","titel":"Wat houd je netto over als zzp’er?: Wil je weten wat jij echt overhoudt?","bron":"/kennisbank/netto-inkomen-berekenen","tags":"","tekst":"In een gratis kennismaking rekenen we het samen door voor jouw situatie, en we vertellen je direct wat je bij ons kost. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"kennisbank/overstappen-boekhouder#101","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Home / Kennisbank / Overstappen  Door Koen Avezaat en Daan Evers. Bijgewerkt in oktober 2026, 4 minuten lezen. Ontevreden over je boekhouder, of toe aan iets anders? Veel zzp’ers stellen overstappen uit omdat het gedoe lijkt. In de praktijk valt het mee, zeker als je het juiste moment kiest en weet wat je nodig hebt."},
{"id":"kennisbank/overstappen-boekhouder#102","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Redenen om over te stappen","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Je hebt elke keer een andere contactpersoon Je krijgt onverwachte rekeningen voor vragen of extra werk Je moet toch nog veel zelf doen in een boekhoudprogramma Je krijgt laat of geen reactie op je vragen"},
{"id":"kennisbank/overstappen-boekhouder#103","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Het beste moment","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Het meest overzichtelijke moment is per 1 januari . Je vorige boekhouder rondt dan het oude jaar af, inclusief de aangifte inkomstenbelasting, en je nieuwe boekhouder begint met een schoon boekjaar. Overstappen aan het begin van een kwartaal kan ook. Spreek dan duidelijk af wie de btw-aangifte van het lopende kwartaal en de aangifte inkomstenbelasting van het vorige jaar doet."},
{"id":"kennisbank/overstappen-boekhouder#104","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Let op bij het opzeggen","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Opzegtermijn: check je contract of de voorwaarden van je huidige boekhouder. Lopende werkzaamheden: spreek af welke aangiftes je huidige boekhouder nog afrondt. Je gegevens: je administratie is van jou. Vraag een export van je boekhouding en kopieën van ingediende aangiftes. Software-abonnement: betaal je zelf voor een boekhoudprogramma? Zeg dat ook op, nadat je je gegevens hebt geëxporteerd."},
{"id":"kennisbank/overstappen-boekhouder#105","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Wat je nieuwe boekhouder nodig heeft","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Je KvK-nummer en btw-identificatienummer De laatst ingediende btw-aangifte De aangifte inkomstenbelasting van vorig jaar De eindbalans, met eventuele bezittingen en afschrijvingen Toegang tot je zakelijke bankrekening voor de koppeling"},
{"id":"kennisbank/overstappen-boekhouder#106","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Overstappen vanuit een eigen boekhoudprogramma","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Doe je je boekhouding nu zelf, bijvoorbeeld in een online programma of Excel? Dan is overstappen meestal nog eenvoudiger. Je nieuwe boekhouder heeft dan nodig: een export van je grootboek of een overzicht van je omzet en kosten van dit jaar; een lijst met openstaande facturen, van klanten en van leveranciers; een overzicht van je bezittingen, zoals een bus, laptop of machines, met aankoopdatum en prijs; je ingediende btw-aangiftes van dit jaar. Exporteer alles vóórdat je je abonnement opzegt. Na het opzeggen ben je vaak snel je toegang kwijt."},
{"id":"kennisbank/overstappen-boekhouder#107","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Machtiging voor je aangiftes","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Om je aangiftes te mogen doen, heeft je nieuwe boekhouder een machtiging van de Belastingdienst nodig. Meestal vraagt je boekhouder die aan, en ontvang jij per post een code die je doorgeeft of activeert. Dat duurt een paar weken, dus begin daar op tijd mee. Je vorige boekhouder kan dan niet meer namens jou aangifte doen voor de periodes die je nieuwe boekhouder overneemt."},
{"id":"kennisbank/overstappen-boekhouder#108","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Dubbele kosten voorkomen","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Kijk naar je opzegtermijn voordat je een overstapdatum kiest. Heeft je huidige boekhouder een opzegtermijn van een maand of drie, en wil je per 1 januari wisselen, dan zeg je uiterlijk eind september op. Zeg je later op, dan betaal je een tijdje voor twee boekhouders, of je stapt later over. Let ook op werk dat je huidige boekhouder nog moet afronden, zoals de laatste btw-aangifte of de jaarcijfers. Vraag vooraf wat dat kost. Sommige kantoren rekenen de jaarafsluiting apart."},
{"id":"kennisbank/overstappen-boekhouder#109","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Hoe lang duurt een overstap?","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Het inrichten van je administratie bij een nieuwe boekhouder kost meestal een tot twee weken. De overdracht van gegevens van je vorige boekhouder kan iets langer duren, maar daar merk je in de praktijk weinig van: je kunt gewoon blijven werken en je bonnetjes aanleveren."},
{"id":"kennisbank/overstappen-boekhouder#110","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Checklist voor je overstap","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Opzegtermijn van je huidige boekhouder gecheckt Afgesproken wie de laatste btw-aangifte en de jaarcijfers doet Export van je administratie en kopieën van je aangiftes Machtiging voor je nieuwe boekhouder geregeld Bankkoppeling in je nieuwe software aangezet"},
{"id":"kennisbank/overstappen-boekhouder#111","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Kan ik midden in een kwartaal overstappen?","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Het kan, maar het is onhandig. De btw-aangifte gaat per kwartaal, dus dan moeten twee boekhouders samen één aangifte maken. Overstappen aan het begin van een kwartaal, of beter nog per 1 januari, is overzichtelijker."},
{"id":"kennisbank/overstappen-boekhouder#112","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Moet ik mijn bank opnieuw koppelen?","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Ja, in de software van je nieuwe boekhouder. Dat duurt een paar minuten. Bij ons koppel je je bank in MoneyMonk; wij helpen je bij de eerste keer."},
{"id":"kennisbank/overstappen-boekhouder#113","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Wat als ik nog een rekening open heb staan bij mijn oude boekhouder?","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Regel die op tijd. Een openstaande rekening kan de overdracht van je gegevens vertragen. Je administratie is van jou, maar een soepele overdracht begint met een nette afronding."},
{"id":"kennisbank/overstappen-boekhouder#114","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Wat kost overstappen?","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Dat verschilt per kantoor. Sommige rekenen niets, andere een vast bedrag voor het inrichten en de overdracht. Bij ons is dat eenmalig €149, en gratis als je per 1 januari overstapt en je uiterlijk 15 december aanmeldt. Overstappen naar Avezaat & Evers? Wij vragen de gegevens op bij je vorige boekhouder en richten alles in. Jij hoeft alleen op te zeggen. Lees hoe het werkt . Geschreven door Koen Avezaat en Daan Evers Boekhouders en oprichters van Avezaat & Evers. Dagelijks bezig met de administratie en aangiftes van zzp’ers. Over ons Dit artikel geeft algemene informatie. Voor je eigen situatie kun je het beste even contact met ons opnemen."},
{"id":"kennisbank/overstappen-boekhouder#115","groep":"Kennisbank","titel":"Overstappen van boekhouder: waar let je op?: Per 1 januari overstappen?","bron":"/kennisbank/overstappen-boekhouder","tags":"","tekst":"Meld je aan t/m 15 december en je stapt gratis over. Plan nu een kennismaking. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"kennisbank/schijnzelfstandigheid#116","groep":"Kennisbank","titel":"Schijnzelfstandigheid in 2026: wat betekent het voor jou als zzp’er?","bron":"/kennisbank/schijnzelfstandigheid","tags":"","tekst":"Home / Kennisbank / Schijnzelfstandigheid  Door Koen Avezaat en Daan Evers. Bijgewerkt in oktober 2026, 4 minuten lezen. Sinds 2025 controleert de Belastingdienst weer actief of zzp’ers echt zelfstandig werken. Daardoor zijn sommige opdrachtgevers voorzichtiger geworden met het inhuren van zzp’ers. In dit artikel lees je hoe de beoordeling werkt, wat er in 2026 en daarna verandert en wat je zelf kunt doen. Stand van zaken: oktober 2026."},
{"id":"kennisbank/schijnzelfstandigheid#117","groep":"Kennisbank","titel":"Schijnzelfstandigheid in 2026: wat betekent het voor jou als zzp’er?: Wat is schijnzelfstandigheid?","bron":"/kennisbank/schijnzelfstandigheid","tags":"","tekst":"Je bent schijnzelfstandig als je op papier zzp’er bent, maar in de praktijk werkt als een werknemer. Dan had je opdrachtgever eigenlijk loonbelasting en premies moeten afdragen, en heb jij recht op bescherming als werknemer, zoals loondoorbetaling bij ziekte. Wat er in je contract staat, is daarbij niet doorslaggevend. Het gaat om hoe je in de praktijk werkt."},
{"id":"kennisbank/schijnzelfstandigheid#118","groep":"Kennisbank","titel":"Schijnzelfstandigheid in 2026: wat betekent het voor jou als zzp’er?: Hoe wordt het beoordeeld?","bron":"/kennisbank/schijnzelfstandigheid","tags":"","tekst":"Er is geen simpele checklist. De Belastingdienst en de rechter kijken naar alle omstandigheden samen. Sinds het Deliveroo-arrest van de Hoge Raad (2023) zijn dit de belangrijkste gezichtspunten: Wie bepaalt hoe en wanneer je werkt? Krijg je instructies over de uitvoering, of bepaal je dat zelf? Hoort je werk bij de organisatie van je opdrachtgever? Werk je mee in een vast team, met een e-mailadres en functie van de opdrachtgever, aan het kernwerk van het bedrijf? Moet je het werk persoonlijk doen, of mag je iemand anders sturen? Hoe word je betaald? Stuur je facturen met btw, en hoe hoog is je tarief? Draag je zelf ondernemersrisico? Bijvoorbeeld als een opdracht misgaat of uitloopt."},
{"id":"kennisbank/schijnzelfstandigheid#119","groep":"Kennisbank","titel":"Schijnzelfstandigheid in 2026: wat betekent het voor jou als zzp’er?: Hoe wordt het beoordeeld?","bron":"/kennisbank/schijnzelfstandigheid","tags":"","tekst":"Gedraag je je als ondernemer? Heb je meerdere opdrachtgevers, werf je zelf klanten en bouw je een eigen naam op? De aard en duur van het werk: een afgebakend project is iets anders dan jarenlang hetzelfde werk doen als de vaste medewerkers. Geen van deze punten is op zichzelf beslissend. Werk je fulltime voor één opdrachtgever, dan is het risico groter, maar dat betekent niet automatisch dat je schijnzelfstandig bent."},
{"id":"kennisbank/schijnzelfstandigheid#120","groep":"Kennisbank","titel":"Schijnzelfstandigheid in 2026: wat betekent het voor jou als zzp’er?: Handhaving: wat geldt nu?","bron":"/kennisbank/schijnzelfstandigheid","tags":"","tekst":"Sinds 1 januari 2025 handhaaft de Belastingdienst weer actief. In 2026 geldt nog een zachte landing: geen verzuimboetes. Een vergrijpboete is wel mogelijk, maar alleen bij opzet of grove schuld, bijvoorbeeld als iemand een eerdere waarschuwing negeert. Naheffingen van loonbelasting en premies gaan naar de opdrachtgever. In principe kijkt de Belastingdienst niet verder terug dan 1 januari 2025. Vanaf 2027 loopt de zachte landing af en kunnen ook verzuimboetes weer worden opgelegd. Voor jou als zzp’er zit het grootste risico vaak niet in een boete, maar in opdrachtgevers die minder zzp’ers inhuren of strengere eisen stellen. Daarnaast kan de Belastingdienst, als je in feite werknemer bent, ook je ondernemerschap voor de inkomstenbelasting ter discussie stellen. Dan kun je de zelfstandigenaftrek en andere ondernemersfaciliteiten kwijtraken."},
{"id":"kennisbank/schijnzelfstandigheid#121","groep":"Kennisbank","titel":"Schijnzelfstandigheid in 2026: wat betekent het voor jou als zzp’er?: Nieuw: het rechtsvermoeden bij een tarief tot €38","bron":"/kennisbank/schijnzelfstandigheid","tags":"","tekst":"De wet die een rechtsvermoeden van een arbeidsovereenkomst invoert, is aangenomen en gaat in op 31 december 2026. Werk je voor een uurtarief van ongeveer €38 of lager, dan kun je je erop beroepen dat je eigenlijk werknemer bent. Je opdrachtgever moet dan bewijzen dat dat niet zo is. In de wet staat €36; dat bedrag wordt jaarlijks geïndexeerd en komt voor de eerste toepassing naar verwachting op €38. Het rechtsvermoeden werkt niet automatisch: jij, een vakbond of bijvoorbeeld een pensioenfonds moet er een beroep op doen. Het gaat om je arbeidsrechtelijke positie. Toch zullen veel opdrachtgevers voorzichtiger worden met zzp’ers die onder dit tarief werken."},
{"id":"kennisbank/schijnzelfstandigheid#122","groep":"Kennisbank","titel":"Schijnzelfstandigheid in 2026: wat betekent het voor jou als zzp’er?: Straks: de Zelfstandigenwet","bron":"/kennisbank/schijnzelfstandigheid","tags":"","tekst":"Het kabinet werkt aan een Zelfstandigenwet, die vooraf duidelijkheid moet geven. Het concept was tot 29 oktober 2026 in internetconsultatie. De bedoeling is dat de wet in januari 2028 ingaat, maar dat is nog niet zeker. Het voorstel bevat twee toetsen: De zelfstandigentoets kijkt naar jou als ondernemer, bijvoorbeeld je inschrijving bij de KvK, of je zelf factureert, hoeveel opdrachtgevers je hebt en of je je hebt ingedekt tegen ondernemersrisico’s. De werkrelatietoets kijkt naar de opdracht: kun je het werk zelf organiseren en doe je het voor eigen rekening en risico? Tot die wet er is, blijft de beoordeling zoals hierboven beschreven."},
{"id":"kennisbank/schijnzelfstandigheid#123","groep":"Kennisbank","titel":"Schijnzelfstandigheid in 2026: wat betekent het voor jou als zzp’er?: Zo laat je zien dat je ondernemer bent","bron":"/kennisbank/schijnzelfstandigheid","tags":"","tekst":"Werk voor meerdere opdrachtgevers, of laat zien dat je daar actief aan werkt. Bepaal zelf je tarief en voorwaarden, en factureer met btw. Spreek een resultaat of project af, geen open einde. Richt het werk zelf in: je eigen werktijden, werkwijze en materialen. Werk aan je eigen naam: een website, een profiel, je eigen e-mailadres. Regel je eigen verzekeringen, zoals een aansprakelijkheids- of arbeidsongeschiktheidsverzekering. Leg afspraken vast, en zorg dat je in de praktijk ook zo werkt."},
{"id":"kennisbank/schijnzelfstandigheid#124","groep":"Kennisbank","titel":"Schijnzelfstandigheid in 2026: wat betekent het voor jou als zzp’er?: Helpt een modelovereenkomst nog?","bron":"/kennisbank/schijnzelfstandigheid","tags":"","tekst":"Een overeenkomst helpt alleen als je in de praktijk ook werkt zoals erin staat. Werk je anders dan op papier, dan telt de praktijk."},
{"id":"kennisbank/schijnzelfstandigheid#125","groep":"Kennisbank","titel":"Schijnzelfstandigheid in 2026: wat betekent het voor jou als zzp’er?: Ik werk via een bemiddelaar of platform. Ben ik dan veilig?","bron":"/kennisbank/schijnzelfstandigheid","tags":"","tekst":"Niet vanzelf. De Belastingdienst kijkt naar de hele keten, en de feitelijke werkrelatie met de partij voor wie je het werk doet blijft bepalend."},
{"id":"kennisbank/schijnzelfstandigheid#126","groep":"Kennisbank","titel":"Schijnzelfstandigheid in 2026: wat betekent het voor jou als zzp’er?: Kan ik zelf een boete krijgen?","bron":"/kennisbank/schijnzelfstandigheid","tags":"","tekst":"Naheffingen gaan in de regel naar de opdrachtgever. Een vergrijpboete kan bij opzet of grove schuld ook de werkende treffen. Daarnaast kan je ondernemerschap voor de inkomstenbelasting ter discussie komen te staan. Bij ons: we kunnen geen juridisch oordeel geven over je arbeidsrelatie, maar we helpen je je administratie en presentatie als ondernemer op orde te houden. Heb je een juridische vraag over een opdracht, dan verwijzen we je door naar een specialist. Geschreven door Koen Avezaat en Daan Evers Boekhouders en oprichters van Avezaat & Evers. Dagelijks bezig met de administratie en aangiftes van zzp’ers. Over ons Dit artikel geeft algemene informatie op basis van de regels en plannen zoals bekend in oktober 2026. Wetgeving rond zzp’ers verandert snel; check bij een concrete situatie de actuele stand of vraag een arbeidsrechtspecialist. Bronnen: Rijksoverheid, Belastingdienst (handhavingsplan arbeidsrelaties), Hoge Raad (Deliveroo, 2023)."},
{"id":"kennisbank/schijnzelfstandigheid#127","groep":"Kennisbank","titel":"Schijnzelfstandigheid in 2026: wat betekent het voor jou als zzp’er?: Je administratie op orde als ondernemer","bron":"/kennisbank/schijnzelfstandigheid","tags":"","tekst":"Wij doen je boekhouding en aangiftes, en denken mee over je opdrachten. Voor €80 per maand. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"kennisbank/starten-met-moneymonk#128","groep":"Kennisbank","titel":"Van start met MoneyMonk","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Home / Kennisbank / Starten met MoneyMonk  Welkom bij Avezaat & Evers! In deze handleiding zet je in ongeveer 20 minuten alles klaar. Daarna lever je alleen nog aan, en doen wij de rest. Voor nieuwe klanten. Bijgewerkt in oktober 2026. Kom je ergens niet uit? Geen probleem. Stuur je eigen boekhouder een bericht of plan je maandelijkse 1-op-1 gesprek in, dan lopen we het samen door."},
{"id":"kennisbank/starten-met-moneymonk#129","groep":"Kennisbank","titel":"Van start met MoneyMonk: Waarom MoneyMonk?","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"MoneyMonk is het boekhoudprogramma waarin wij jouw administratie bijhouden. Jij gebruikt het om bonnetjes en facturen aan te leveren; wij verwerken alles en doen je aangiftes. Het abonnement zit in je pakket, je betaalt er niets extra voor."},
{"id":"kennisbank/starten-met-moneymonk#130","groep":"Kennisbank","titel":"Van start met MoneyMonk: Stap 1 – Accepteer je uitnodiging","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Wij maken je administratie voor je aan. Je ontvangt daarna een e-mail van MoneyMonk met een uitnodiging. Open de e-mail en klik op de link om je account te activeren. Kies een sterk wachtwoord. Zet, als MoneyMonk dat aanbiedt, tweestapsverificatie aan. Het gaat tenslotte om je financiële gegevens. Geen e-mail ontvangen? Kijk in je spammap, of laat het ons weten."},
{"id":"kennisbank/starten-met-moneymonk#131","groep":"Kennisbank","titel":"Van start met MoneyMonk: Stap 2 – Download de app","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Zoek op MoneyMonk in de App Store (iPhone) of Google Play (Android) en log in met je nieuwe account. Met de app maak je onderweg een foto van een bonnetje, zodat je het nooit meer kwijtraakt."},
{"id":"kennisbank/starten-met-moneymonk#132","groep":"Kennisbank","titel":"Van start met MoneyMonk: Stap 3 – Koppel je zakelijke bankrekening","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Via de bankkoppeling komen je transacties automatisch in je administratie. Dit is de belangrijkste stap: hierdoor is er per maand maar weinig werk nodig. Kies in MoneyMonk voor het koppelen van je bankrekening. Selecteer je bank en log in via de beveiligde omgeving van je eigen bank. Geef toestemming. Koppel alle zakelijke rekeningen die je gebruikt, ook een spaarrekening voor de belasting. De gratis koppeling werkt met onder meer ABN AMRO, ING, Rabobank, bunq, Knab, ASN Bank, SNS, RegioBank, Triodos en N26, en ook met Mollie. Revolut, Wise, PayPal en Stripe koppel je automatisch via Ponto. Je bank vraagt periodiek om de koppeling te vernieuwen. Je krijgt dan een melding; vernieuw hem direct, anders missen wij transacties. Tip: gebruik je zakelijke rekening alleen voor zakelijke uitgaven. Dat scheelt uitzoekwerk en vragen."},
{"id":"kennisbank/starten-met-moneymonk#133","groep":"Kennisbank","titel":"Van start met MoneyMonk: Stap 4 – Facturen maken in MoneyMonk (optioneel)","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Je hoeft je verkoopfacturen niet in MoneyMonk te maken. Gebruik je liever je eigen programma of template? Prima, dan lever je de factuur gewoon aan zoals een bonnetje (zie stap 5). Wel handig: facturen die je in MoneyMonk maakt, staan direct in je administratie en worden automatisch gekoppeld aan de betaling. Kies je daarvoor, vul dan één keer je gegevens in, dan staan ze op elke factuur: Je logo (optioneel) Bedrijfsnaam, adres en contactgegevens KvK-nummer en btw-identificatienummer Je IBAN en een standaard betaaltermijn, bijvoorbeeld 14 dagen Gebruik je de kleineondernemersregeling (KOR)? Laat het ons weten, dan zetten we je facturen goed in."},
{"id":"kennisbank/starten-met-moneymonk#134","groep":"Kennisbank","titel":"Van start met MoneyMonk: Stap 5 – Zo lever je aan","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Alles wat je zakelijk betaalt of ontvangt, moet in je administratie. Kies wat jou het makkelijkst uitkomt: Wat Hoe Bonnetje uit een winkel Foto maken in de app Factuur per e-mail Doorsturen naar je MoneyMonk-mailadres, of uploaden via de app of computer Factuur als pdf op je computer Uploaden in MoneyMonk op je computer Je eigen verkoopfacturen Gemaakt in MoneyMonk? Dan staan ze er al in. Elders gemaakt? Uploaden of doorsturen, net als een inkoopfactuur De gouden regel: lever binnen een paar dagen aan, en uiterlijk op de 10e na afloop van elk kwartaal . Dan kunnen wij je btw-aangifte op tijd en zonder stress indienen."},
{"id":"kennisbank/starten-met-moneymonk#135","groep":"Kennisbank","titel":"Van start met MoneyMonk: Stap 6 – Uren en ritten bijhouden","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Wil je je uren of zakelijke kilometers bijhouden, bijvoorbeeld voor de zelfstandigenaftrek of je kilometervergoeding? Dat doe je met de uren- en rittenregistratie in de app. Die zit gewoon in je pakket."},
{"id":"kennisbank/starten-met-moneymonk#136","groep":"Kennisbank","titel":"Van start met MoneyMonk: Wat doen wij?","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"We koppelen je bonnetjes en facturen aan de juiste banktransacties. We controleren alles en vragen het je als er iets ontbreekt. Elk kwartaal dienen we je btw-aangifte in. Je ziet vooraf wat je moet betalen. Na afloop van het jaar maken we je jaarcijfers en doen we je aangifte inkomstenbelasting."},
{"id":"kennisbank/starten-met-moneymonk#137","groep":"Kennisbank","titel":"Van start met MoneyMonk: Checklist voor je eerste week","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Account geactiveerd App gedownload en ingelogd Alle zakelijke rekeningen gekoppeld Factuurgegevens ingevuld (als je in MoneyMonk factureert) Bonnetjes van deze maand aangeleverd Eerste 1-op-1 gesprek ingepland (optioneel) Je vinkjes worden op dit apparaat onthouden."},
{"id":"kennisbank/starten-met-moneymonk#138","groep":"Kennisbank","titel":"Van start met MoneyMonk: Aanleveren","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Hoe snel moet ik aanleveren? Het liefst binnen een paar dagen na een aankoop of verkoop, dan vergeet je niets. De harde deadline is de 10e na afloop van elk kwartaal, zodat wij je btw-aangifte op tijd kunnen indienen. Wat als ik te laat aanlever? Dan kunnen we niet garanderen dat je aangifte op tijd wordt ingediend. Lukt het ons toch met spoed, dan rekenen we €50 per aangifte. Weet je dat je later bent? Laat het ons dan zo vroeg mogelijk weten. Ik ben een bonnetje kwijt. Wat nu? Vraag de leverancier om een kopie, of zoek de factuur op in je e-mail of in je account bij de webshop. Lukt dat niet, laat het ons weten; dan kijken we samen wat mogelijk is. Moet ik contante betalingen ook aanleveren? Ja. Maak een foto van het bonnetje en zet er een korte notitie bij dat je contant hebt betaald. Zonder bankafschrift is het bonnetje je enige bewijs. Moet ik mijn verkoopfacturen in MoneyMonk maken? Nee, dat mag maar het hoeft niet. Maak je ze elders, lever ze dan aan zoals een inkoopfactuur. Facturen uit MoneyMonk staan wel direct in je administratie, dat scheelt je een stap."},
{"id":"kennisbank/starten-met-moneymonk#139","groep":"Kennisbank","titel":"Van start met MoneyMonk: Bank en betalingen","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Ik heb iets privé betaald met mijn zakelijke rekening. Geen probleem, dat gebeurt iedereen. Zet er een korte notitie bij in MoneyMonk of laat het ons weten, dan boeken we het als privé. Mijn bankkoppeling werkt niet meer. Je bank vraagt periodiek om de koppeling te vernieuwen. Je krijgt daar een melding van; volg die stappen. Lukt het niet, laat het ons weten, want zonder koppeling missen wij transacties. Ik bankier bij Revolut of Wise. Kan ik koppelen? Ja. Je koppelt je rekening automatisch via Ponto, een koppeldienst die MoneyMonk daarvoor gebruikt. Of je downloadt elke maand je transacties als bestand (CSV of MT940) en zet dat in MoneyMonk. Twijfel je? We kiezen bij de start samen wat voor jou het handigst is. Ik heb meerdere rekeningen of een zakelijke creditcard. Koppel alle zakelijke rekeningen, ook je spaarrekening voor de belasting."},
{"id":"kennisbank/starten-met-moneymonk#140","groep":"Kennisbank","titel":"Van start met MoneyMonk: Bank en betalingen","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Voor een creditcard lever je het maandoverzicht aan, plus de bonnetjes van wat je ermee hebt betaald. Ik zie een transactie die ik niet herken. Laat het ons weten. Als wij een transactie niet kunnen plaatsen, vragen we het jou ook, zodat er niets fout geboekt wordt."},
{"id":"kennisbank/starten-met-moneymonk#141","groep":"Kennisbank","titel":"Van start met MoneyMonk: Btw en aangiftes","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Wanneer hoor ik hoeveel btw ik moet betalen? Na het verwerken van het kwartaal sturen we je vóór de deadline een overzicht met het bedrag. Zo kom je nooit voor verrassingen te staan. Wie betaalt de btw aan de Belastingdienst? Wij doen de aangifte, jij maakt het bedrag over naar de Belastingdienst. Het geld gaat dus nooit via ons. Zorg dat je het bedrag vóór de deadline betaalt. Moet ik zelf iets boeken? Nee. Jij levert aan; het boeken, controleren en de aangiftes doen wij."},
{"id":"kennisbank/starten-met-moneymonk#142","groep":"Kennisbank","titel":"Van start met MoneyMonk: Account en kosten","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Kost MoneyMonk me iets extra? Nee, de software en de app zitten in je pakket, inclusief de uren- en rittenregistratie. Kunnen jullie alles zien in mijn administratie? Ja. Wij werken in dezelfde administratie als jij. We zien je banktransacties en alles wat je aanlevert, zodat we je boekhouding kunnen verwerken. We gaan daar vertrouwelijk mee om. Is mijn informatie veilig? MoneyMonk heeft een vergunning van De Nederlandsche Bank voor de bankkoppeling. Wij werken met tweestapsverificatie op onze accounts en delen je gegevens alleen waar dat nodig is, zoals bij je aangiftes. Wat gebeurt er met mijn administratie als ik opzeg? Je administratie is van jou. Bij opzegging zorgen we dat je een export van je gegevens krijgt, zodat je die kunt meenemen naar een nieuwe boekhouder. Let op: je moet je administratie 7 jaar bewaren."},
{"id":"kennisbank/starten-met-moneymonk#143","groep":"Kennisbank","titel":"Van start met MoneyMonk: Account en kosten","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Staat je vraag er niet bij? Stuur je eigen boekhouder een bericht, of mail naar info@avezaatenevers.nl . MoneyMonk is een product van MoneyMonk B.V. Schermen en menunamen in de app kunnen in de loop van de tijd veranderen. Zie je iets anders dan hier staat? Laat het ons weten, dan passen we deze handleiding aan."},
{"id":"kennisbank/starten-met-moneymonk#144","groep":"Kennisbank","titel":"Van start met MoneyMonk: Nog geen klant?","bron":"/kennisbank/starten-met-moneymonk","tags":"","tekst":"Zo makkelijk werkt het dus. Plan een gratis kennismaking en ontdek of we bij je passen. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"kennisbank/voorlopige-aanslag#145","groep":"Kennisbank","titel":"Voorlopige aanslag inkomstenbelasting: zo voorkom je een naheffing","bron":"/kennisbank/voorlopige-aanslag","tags":"","tekst":"Home / Kennisbank / Voorlopige aanslag  Door Koen Avezaat en Daan Evers. Bijgewerkt in oktober 2026, 4 minuten lezen. Als zzp’er houdt niemand belasting in op je inkomen. In plaats daarvan stuurt de Belastingdienst je een voorlopige aanslag: een schatting van wat je over dit jaar gaat betalen, verdeeld over maandelijkse termijnen. Klopt die schatting niet, dan krijg je achteraf een naheffing of geld terug."},
{"id":"kennisbank/voorlopige-aanslag#146","groep":"Kennisbank","titel":"Voorlopige aanslag inkomstenbelasting: zo voorkom je een naheffing: Hoe komt de Belastingdienst aan het bedrag?","bron":"/kennisbank/voorlopige-aanslag","tags":"","tekst":"De Belastingdienst baseert de voorlopige aanslag meestal op je laatst bekende inkomen, bijvoorbeeld je aangifte van twee jaar geleden. Is je bedrijf sindsdien gegroeid, dan is de voorlopige aanslag te laag. Je betaalt dan het hele jaar te weinig en krijgt na je aangifte een rekening voor het verschil. Naast de inkomstenbelasting krijg je vaak ook een aparte voorlopige aanslag voor de bijdrage Zorgverzekeringswet (Zvw)."},
{"id":"kennisbank/voorlopige-aanslag#147","groep":"Kennisbank","titel":"Voorlopige aanslag inkomstenbelasting: zo voorkom je een naheffing: Rekenvoorbeeld: groeiende winst","bron":"/kennisbank/voorlopige-aanslag","tags":"","tekst":"Winst waar de voorlopige aanslag van uitgaat €25.000 Je werkelijke winst dit jaar €45.000 Extra winst waar je nog niets over betaald hebt €20.000 Extra inkomstenbelasting en Zvw (2026, zonder andere inkomsten) ongeveer €5.800 Die €5.800 moet je in één keer betalen als je de definitieve aanslag krijgt, vaak anderhalf jaar later. Heb je dat geld niet apart gezet, dan zit je krap. Met onze netto-inkomen-calculator zie je hoeveel je ongeveer moet reserveren."},
{"id":"kennisbank/voorlopige-aanslag#148","groep":"Kennisbank","titel":"Voorlopige aanslag inkomstenbelasting: zo voorkom je een naheffing: Wanneer pas je hem aan?","bron":"/kennisbank/voorlopige-aanslag","tags":"","tekst":"Je verdient duidelijk meer dan het bedrag waar de aanslag van uitgaat. Dan verhoog je hem en betaal je per maand een beetje meer, in plaats van later in één keer. Je verdient minder , bijvoorbeeld door een rustig jaar of ziekte. Dan verlaag je hem, zodat je niet maandenlang te veel vooruitbetaalt. Je bent net gestart. Dan heb je vaak nog geen voorlopige aanslag. Vraag er zelf een aan, zodat je niet alles in één keer hoeft te betalen. Aanpassen of aanvragen doe je via Mijn Belastingdienst, of je boekhouder doet het voor je."},
{"id":"kennisbank/voorlopige-aanslag#149","groep":"Kennisbank","titel":"Voorlopige aanslag inkomstenbelasting: zo voorkom je een naheffing: Belastingrente voorkomen","bron":"/kennisbank/voorlopige-aanslag","tags":"","tekst":"Komt de definitieve aanslag over 2026 later dan 1 juli 2027 en moet je bijbetalen, dan rekent de Belastingdienst belastingrente. In 2026 is die rente voor de inkomstenbelasting 5%. Je voorkomt dit door vóór 1 mei je aangifte in te dienen, of vóór 1 mei een voorlopige aanslag aan te vragen die zo goed mogelijk klopt. Wijkt de uiteindelijke aanslag veel af van je schatting, dan kan er toch rente bijkomen."},
{"id":"kennisbank/voorlopige-aanslag#150","groep":"Kennisbank","titel":"Voorlopige aanslag inkomstenbelasting: zo voorkom je een naheffing: Te veel betaald?","bron":"/kennisbank/voorlopige-aanslag","tags":"","tekst":"Heb je te veel vooruitbetaald, dan krijg je het verschil terug na je aangifte. Dat is fijn, maar het betekent wel dat je een jaar lang geld hebt uitgeleend aan de Belastingdienst, terwijl je het in je bedrijf had kunnen gebruiken. Een voorlopige aanslag die goed aansluit op je echte winst is dus het beste."},
{"id":"kennisbank/voorlopige-aanslag#151","groep":"Kennisbank","titel":"Voorlopige aanslag inkomstenbelasting: zo voorkom je een naheffing: Onze tip: zet elke maand geld apart","bron":"/kennisbank/voorlopige-aanslag","tags":"","tekst":"Ook met een goede voorlopige aanslag is het verstandig om een buffer aan te houden. Zet van elke betaling die binnenkomt de btw en een deel voor de inkomstenbelasting apart op een spaarrekening. Dan ben je nooit verrast. Zo bepaal je hoeveel."},
{"id":"kennisbank/voorlopige-aanslag#152","groep":"Kennisbank","titel":"Voorlopige aanslag inkomstenbelasting: zo voorkom je een naheffing: Zo pas je je voorlopige aanslag aan","bron":"/kennisbank/voorlopige-aanslag","tags":"","tekst":"Log in op Mijn Belastingdienst met DigiD. Kies voor het wijzigen of aanvragen van een voorlopige aanslag voor het juiste jaar. Vul je verwachte winst in. Gebruik je cijfers tot nu toe en een eerlijke inschatting van de rest van het jaar. Controleer de aftrekposten, zoals de zelfstandigenaftrek, en verstuur. Je krijgt daarna een nieuwe voorlopige aanslag met aangepaste termijnen. Hoe later in het jaar je hem aanpast, hoe minder termijnen er over zijn en hoe hoger elk bedrag wordt. Aanpassen in het voorjaar is dus prettiger dan in november."},
{"id":"kennisbank/voorlopige-aanslag#153","groep":"Kennisbank","titel":"Voorlopige aanslag inkomstenbelasting: zo voorkom je een naheffing: Ben ik verplicht een voorlopige aanslag te hebben?","bron":"/kennisbank/voorlopige-aanslag","tags":"","tekst":"Nee. Maar zonder voorlopige aanslag betaal je alles in één keer na je aangifte, en loop je meer kans op belastingrente. Voor de meeste ondernemers is betalen in termijnen veel prettiger."},
{"id":"kennisbank/voorlopige-aanslag#154","groep":"Kennisbank","titel":"Voorlopige aanslag inkomstenbelasting: zo voorkom je een naheffing: Ik kan de voorlopige aanslag niet betalen. Wat nu?","bron":"/kennisbank/voorlopige-aanslag","tags":"","tekst":"Kijk eerst of de aanslag klopt. Is hij te hoog, pas hem dan aan. Klopt hij wel maar lukt betalen niet, dan kun je bij de Belastingdienst een betalingsregeling aanvragen. Doe dat op tijd, voordat er aanmaningen komen."},
{"id":"kennisbank/voorlopige-aanslag#155","groep":"Kennisbank","titel":"Voorlopige aanslag inkomstenbelasting: zo voorkom je een naheffing: Krijg ik ook een voorlopige aanslag voor de Zvw?","bron":"/kennisbank/voorlopige-aanslag","tags":"","tekst":"Ja. De inkomensafhankelijke bijdrage Zorgverzekeringswet komt op een aparte aanslag. In 2026 is die 4,85% van je inkomen tot een maximum. Pas je je voorlopige aanslag inkomstenbelasting aan, dan wordt die voor de Zvw meestal mee aangepast."},
{"id":"kennisbank/voorlopige-aanslag#156","groep":"Kennisbank","titel":"Voorlopige aanslag inkomstenbelasting: zo voorkom je een naheffing: Wat is het verschil met de definitieve aanslag?","bron":"/kennisbank/voorlopige-aanslag","tags":"","tekst":"De voorlopige aanslag is een schatting vooraf. Na je aangifte stelt de Belastingdienst de definitieve aanslag vast. Het verschil betaal je bij, of krijg je terug. Bij ons: je vaste boekhouder loopt dit elk jaar met je door, ruim voor de jaarwisseling. Vragen stellen is altijd inbegrepen. Geschreven door Koen Avezaat en Daan Evers Boekhouders en oprichters van Avezaat & Evers. Dagelijks bezig met de administratie en aangiftes van zzp’ers. Over ons Dit artikel geeft algemene informatie. Voor je eigen situatie kun je het beste even contact met ons opnemen, of kijken op de website van de Belastingdienst."},
{"id":"kennisbank/voorlopige-aanslag#157","groep":"Kennisbank","titel":"Voorlopige aanslag inkomstenbelasting: zo voorkom je een naheffing: Geen verrassingen meer","bron":"/kennisbank/voorlopige-aanslag","tags":"","tekst":"Wij houden je voorlopige aanslag in de gaten en passen hem aan als je meer of minder verdient. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"kennisbank/zelfstandigenaftrek#158","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Home / Kennisbank / Zelfstandigenaftrek  Door Koen Avezaat en Daan Evers. Bijgewerkt in oktober 2026, 8 minuten lezen. Kort antwoord. De zelfstandigenaftrek is € 1.200 in 2026 en daalt naar € 900 in 2027 . Je hebt er recht op als je ondernemer bent voor de inkomstenbelasting en minimaal 1.225 uur per jaar aan je bedrijf werkt. Starters krijgen in 2026 nog € 2.123 startersaftrek extra. Volgens het Belastingplan 2027 is dat in 2027 nog maar € 10 en verdwijnt de startersaftrek in 2028 helemaal. De zelfstandigenaftrek is een van de bekendste belastingvoordelen voor zzp’ers. Toch levert de aftrek elk jaar minder op. In dit artikel lees je hoe hoog de aftrek is, of je er recht op hebt, welke uren meetellen voor het urencriterium en wat de afbouw in 2027 voor jou betekent."},
{"id":"kennisbank/zelfstandigenaftrek#159","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Wat is de zelfstandigenaftrek?","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"De zelfstandigenaftrek is een vast bedrag dat je van je winst mag aftrekken voordat je inkomstenbelasting betaalt. Je betaalt dus belasting over een lager bedrag. Het is geen bedrag dat je uitbetaald krijgt: het verlaagt alleen je belastbare winst. De aftrek hoort bij de ondernemersaftrek . Daaronder vallen ook de startersaftrek, de meewerkaftrek (als je partner onbetaald meewerkt) en een paar kleinere regelingen. Na de ondernemersaftrek gaat er nog eens 12,7% mkb-winstvrijstelling van je winst af. Die krijg je ook zonder urencriterium."},
{"id":"kennisbank/zelfstandigenaftrek#160","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Hoe hoog is de zelfstandigenaftrek?","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Sinds 2023 wordt de zelfstandigenaftrek snel afgebouwd. Zo ziet dat eruit: Jaar Zelfstandigenaftrek Startersaftrek 2023 € 5.030 € 2.123 2024 € 3.750 € 2.123 2025 € 2.470 € 2.123 2026 € 1.200 € 2.123 2027 € 900 € 10 (voorstel) 2028 € 900 vervalt (voorstel) De verlaging naar € 900 in 2027 staat al in de wet. De bedragen voor de startersaftrek in 2027 en 2028 komen uit het Belastingplan 2027 dat op Prinsjesdag 2026 is gepresenteerd. De Tweede en Eerste Kamer moeten dat plan nog goedkeuren. We werken deze pagina bij zodra het definitief is."},
{"id":"kennisbank/zelfstandigenaftrek#161","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Wat levert de zelfstandigenaftrek je op?","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Minder dan je misschien denkt. Je krijgt niet € 1.200 terug: je betaalt over € 1.200 minder winst belasting. Wat dat oplevert, hangt af van je inkomen. Wij hebben het doorgerekend voor een zzp’er zonder andere inkomsten, met de inkomstenbelasting, heffingskortingen en de Zvw-bijdrage: Winst per jaar Voordeel zelfstandigenaftrek 2026 Voordeel 2027 € 25.000 ± € 100 ± € 90 € 40.000 ± € 470 ± € 360 € 60.000 ± € 580 ± € 440 Bij een lage winst levert de aftrek weinig op, omdat de heffingskortingen je belasting dan al grotendeels wegstrepen. Bij een winst boven € 78.426 (2026) is het voordeel beperkt: dan mag je de ondernemersaftrek en de mkb-winstvrijstelling maximaal tegen 37,56% aftrekken, ook al betaal je zelf 49,5% over dat deel van je inkomen. Benieuwd naar jouw eigen situatie? Met onze netto-inkomen calculator zie je in een paar seconden wat je overhoudt, met en zonder urencriterium."},
{"id":"kennisbank/zelfstandigenaftrek#162","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Wie heeft recht op de zelfstandigenaftrek?","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Je hebt recht op de zelfstandigenaftrek als je aan twee voorwaarden voldoet: Je bent ondernemer voor de inkomstenbelasting. Je hebt een eenmanszaak of bent vennoot in een vof, maakt winst (of verwacht dat), werkt voor meerdere opdrachtgevers en loopt ondernemersrisico. Een inschrijving bij de KvK alleen is niet genoeg. Twijfel je? De OndernemersCheck van de Belastingdienst geeft een eerste indicatie. Je voldoet aan het urencriterium. Je werkt minimaal 1.225 uur per kalenderjaar aan je onderneming. Heb je ook een baan in loondienst, dan geldt een extra eis (zie hieronder). Heb je een bv? Dan heb je geen recht op de zelfstandigenaftrek. De aftrek bestaat alleen in de inkomstenbelasting."},
{"id":"kennisbank/zelfstandigenaftrek#163","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Het urencriterium uitgelegd","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Het urencriterium is de voorwaarde waar het in de praktijk het vaakst op misgaat. 1.225 uur per jaar komt neer op ongeveer 24 uur per week, als je 51 weken werkt. Het gaat om uren die je echt aan je bedrijf besteedt, niet om de uren die je factureert."},
{"id":"kennisbank/zelfstandigenaftrek#164","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Deze uren tellen mee","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Uren voor klanten en opdrachten (declarabele uren) Administratie: facturen maken, bonnetjes verwerken, je boekhouding bijhouden Acquisitie: offertes maken, netwerken, klanten bellen. Ook als de opdracht niet doorgaat Marketing: aan je website werken, social media, je portfolio bijwerken Cursussen en opleidingen die met je werk te maken hebben Reistijd voor je werk, bijvoorbeeld naar een klant of leverancier Inkoop, onderhoud van je gereedschap of materiaal en het voorbereiden van klussen"},
{"id":"kennisbank/zelfstandigenaftrek#165","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Deze uren tellen niet mee","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Vakantie en ziektedagen Uren waarin je alleen beschikbaar bent, zonder dat je werk voor je bedrijf doet Uren die je in loondienst werkt, ook als het werk op je eigen bedrijf lijkt"},
{"id":"kennisbank/zelfstandigenaftrek#166","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Werk je ook in loondienst? Dan geldt de 50%-regel","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Heb je naast je onderneming een baan? Dan moet je méér dan de helft van je totale werktijd aan je bedrijf besteden. Werk je bijvoorbeeld 1.248 uur per jaar in loondienst (drie dagen per week), dan moet je minimaal 1.249 uur aan je onderneming werken, niet 1.225. Uitzondering voor starters: was je in één of meer van de vijf jaren daarvoor geen ondernemer, dan hoef je niet aan deze 50%-regel te voldoen. De 1.225 uur blijft wel gelden."},
{"id":"kennisbank/zelfstandigenaftrek#167","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Zwangerschap","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Ben je zwanger? Dan mag je de niet-gewerkte uren tijdens 16 weken zwangerschapsverlof meetellen voor het urencriterium."},
{"id":"kennisbank/zelfstandigenaftrek#168","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Houd een urenregistratie bij","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Jij moet kunnen aantonen dat je aan het urencriterium voldoet, niet de Belastingdienst. Een schatting achteraf is bij een controle vaak niet genoeg. Noteer daarom elke dag of week je uren per activiteit en bewaar ondersteunend bewijs, zoals je agenda, e-mails met klanten, facturen en reisgegevens. In MoneyMonk kun je je uren direct in de app bijhouden."},
{"id":"kennisbank/zelfstandigenaftrek#169","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: De startersaftrek","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Ben je net begonnen? Dan kun je naast de zelfstandigenaftrek ook de startersaftrek krijgen. In 2026 is dat € 2.123 extra. De voorwaarden: Je hebt recht op de zelfstandigenaftrek (dus je haalt ook het urencriterium). Je was in de vijf jaar daarvoor niet elk jaar ondernemer. Je hebt in die vijf jaar maximaal twee keer de zelfstandigenaftrek gebruikt. Je kunt de startersaftrek maximaal drie keer krijgen. Start je in 2026? Dan levert die in dat jaar nog flink wat op: bij € 40.000 winst ongeveer € 835 extra. Let op voor 2027. Volgens het Belastingplan 2027 daalt de startersaftrek naar € 10 en vervalt de startersaftrek vanaf 2028 helemaal, zonder overgangsregeling. Start je eind 2026 of in 2027? Reken dan niet op de startersaftrek in je planning. Meer weten over beginnen als zzp’er? Lees onze pagina voor starters ."},
{"id":"kennisbank/zelfstandigenaftrek#170","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Wat als de aftrek hoger is dan je winst?","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"De zelfstandigenaftrek mag niet hoger zijn dan je winst. Maak je in 2026 bijvoorbeeld € 800 winst, dan trek je ook maar € 800 af. Het deel dat je niet kunt gebruiken, heet de niet-gerealiseerde zelfstandigenaftrek . Dat mag je verrekenen in de negen jaar daarna, in jaren waarin je wel genoeg winst maakt. Voor starters geldt een uitzondering: als je recht hebt op de startersaftrek, mag je de volledige zelfstandigenaftrek aftrekken, ook als die hoger is dan je winst. Daardoor ontstaat een verlies dat je kunt verrekenen met ander inkomen, bijvoorbeeld uit loondienst."},
{"id":"kennisbank/zelfstandigenaftrek#171","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Heb je de AOW-leeftijd bereikt?","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Had je op 1 januari van het jaar de AOW-leeftijd al bereikt? Dan krijg je de helft van de zelfstandigenaftrek: € 600 in 2026. Het urencriterium blijft gewoon gelden."},
{"id":"kennisbank/zelfstandigenaftrek#172","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Hoe vraag je de zelfstandigenaftrek aan?","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Je hoeft de aftrek niet apart aan te vragen. Je geeft in je aangifte inkomstenbelasting aan dat je aan het urencriterium voldoet, en dan wordt de aftrek automatisch meegenomen. Die aangifte doe je in het voorjaar over het jaar ervoor: de aftrek over 2026 krijg je dus via je aangifte in 2027. Wil je het voordeel al eerder? Dan kun je een voorlopige aanslag aanvragen. Daarin houdt de Belastingdienst al rekening met de aftrek, zodat je maandelijks een realistischer bedrag betaalt of terugkrijgt."},
{"id":"kennisbank/zelfstandigenaftrek#173","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Wat betekent de afbouw voor jou?","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Je betaalt elk jaar iets meer belasting bij dezelfde winst. Zet daarom niet hetzelfde percentage opzij als een paar jaar geleden. De calculator laat zien hoeveel je per maand moet reserveren. Pas je voorlopige aanslag aan. Is die gebaseerd op een oud jaar, dan kan er na je aangifte een flinke naheffing volgen. Het urencriterium blijft belangrijk. De aftrek wordt kleiner, maar het urencriterium bepaalt ook of je andere regelingen krijgt, zoals de startersaftrek en de meewerkaftrek. Blijf dus je uren bijhouden. Gebruik andere aftrekposten wel volledig. Zakelijke kosten en de kleinschaligheidsinvesteringsaftrek wegen steeds zwaarder nu de vaste aftrek kleiner wordt. Een complete administratie levert dus meer op dan ooit."},
{"id":"kennisbank/zelfstandigenaftrek#174","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Veelgestelde vragen","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Hoeveel is de zelfstandigenaftrek in 2027? € 900. Dat bedrag staat al in de wet. De startersaftrek is volgens het Belastingplan 2027 in dat jaar nog € 10. Hoeveel uur moet ik werken voor de zelfstandigenaftrek? Minimaal 1.225 uur per kalenderjaar, ongeveer 24 uur per week. Heb je ook een baan in loondienst, dan moet je bovendien meer dan de helft van je werktijd aan je bedrijf besteden, tenzij je een starter bent. Tellen administratie en acquisitie mee voor het urencriterium? Ja. Ook indirecte uren tellen mee, zoals je boekhouding, offertes maken, netwerken, aan je website werken en vakgerichte cursussen. Krijg ik de zelfstandigenaftrek met een parttime baan ernaast? Alleen als je minimaal 1.225 uur aan je bedrijf werkt én meer uren aan je bedrijf besteedt dan aan je baan. Starters hoeven niet aan die tweede eis te voldoen."},
{"id":"kennisbank/zelfstandigenaftrek#175","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Veelgestelde vragen","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Wat gebeurt er als ik het urencriterium niet haal? Dan krijg je geen zelfstandigenaftrek en geen startersaftrek. De mkb-winstvrijstelling van 12,7% krijg je wel, als je ondernemer bent voor de inkomstenbelasting. Verdwijnt de zelfstandigenaftrek helemaal? Nee, niet volgens de huidige plannen. Hij daalt naar € 900 in 2027. De startersaftrek verdwijnt volgens het Belastingplan 2027 wel, vanaf 2028. Bij ons zit je hier altijd goed. We controleren elk jaar of je recht hebt op de zelfstandigenaftrek en startersaftrek, verwerken die in je aangifte inkomstenbelasting en laten je vooraf weten wat je moet reserveren. Geschreven door Koen Avezaat en Daan Evers Boekhouders en oprichters van Avezaat & Evers. Dagelijks bezig met de administratie en aangiftes van zzp’ers. Over ons Dit artikel geeft algemene informatie op basis van de regels zoals bekend in oktober 2026. Bedragen voor 2027 zijn deels nog voorstellen. Voor je eigen situatie kun je het beste even contact met ons opnemen, of kijken op de website van de Belastingdienst."},
{"id":"kennisbank/zelfstandigenaftrek#176","groep":"Kennisbank","titel":"Zelfstandigenaftrek 2026 en 2027: bedragen, urencriterium en voorwaarden: Zeker weten dat je alle aftrekposten krijgt?","bron":"/kennisbank/zelfstandigenaftrek","tags":"","tekst":"Wij doen je aangifte inkomstenbelasting en controleren je recht op zelfstandigen- en startersaftrek. Inbegrepen in je pakket van €80 per maand. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"tarieven#177","groep":"Website","titel":"Tarieven","bron":"/tarieven","tags":"","tekst":"Home /  Tarieven Eén pakket, één prijs. Geen gedoe met tiers of limieten waar je steeds overheen dreigt te gaan."},
{"id":"tarieven#178","groep":"Website","titel":"Tarieven: Boekhouding volledig uit handen","bron":"/tarieven","tags":"","tekst":"Eén pakket voor vrijwel elke zzp’er en eenmanszaak €80 p/m excl. btw €96,80 incl. btw, maandelijks opzegbaar Niet tevreden na de eerste maand? Geld terug Tot 100 banktransacties per maand Boekhouding volledig verzorgd 4× btw-aangifte per jaar Aangifte inkomstenbelasting Jaarcijfers: winst- en verliesrekening en balans Eén vaste boekhouder die je bedrijf kent Elke maand een 1-op-1 gesprek in te plannen Software en app, met uren- en rittenregistratie Plan een gratis kennismaking Bereken je prijs"},
{"id":"tarieven#179","groep":"Website","titel":"Tarieven: Alleen als je het nodig hebt","bron":"/tarieven","tags":"","tekst":"Meer dan 100 transacties per maand prijs op maat ICP-aangifte (klanten binnen de EU) €15 p/m IB-aangifte fiscaal partner €150 p/jaar Overstappen (eenmalig) €149 Achterstallige administratie €60 p/uur Overstappen per 1 januari? Dan is het gratis bij aanmelding t/m 15 december. Zonder risico"},
{"id":"tarieven#180","groep":"Website","titel":"Tarieven: Niet tevreden na je eerste maand? Geld terug.","bron":"/tarieven","tags":"","tekst":"We weten zeker dat je het fijn vindt om je boekhouding uit handen te geven. Is dat na een maand toch niet zo, dan krijg je het maandbedrag gewoon terug. Zonder vragen en zonder gedoe. Plan een gratis kennismaking"},
{"id":"tarieven#181","groep":"Website","titel":"Tarieven: Wat is je tijd waard?","bron":"/tarieven","tags":"","tekst":"Een zzp’er rekent gemiddeld €83 per uur . Ben je meer dan een uur per maand met je administratie bezig, dan ben je met ons pakket al goedkoper uit. Gemiddeld uurtarief excl. btw volgens onderzoek van Knab onder ruim 20.000 zelfstandigen (2026). Bron: Knab . Het uurtarief verschilt per branche. Tijd aan administratie Waarde van je tijd* Ons pakket 1 uur per maand €83 €80 2 uur per maand €166 €80 4 uur per maand €332 €80 * Uitgaande van €83 per uur. Bedragen excl. btw. De kosten van een boekhouder zijn bovendien aftrekbaar."},
{"id":"tarieven#182","groep":"Website","titel":"Tarieven: Niet in het pakket","bron":"/tarieven","tags":"","tekst":"Hiervoor maken we vooraf een prijsafspraak, zodat je nooit voor verrassingen komt te staan. Aanvragen of wijzigen van toeslagen op aanvraag Bezwaarschriften op aanvraag Loonadministratie voor personeel, samen met een salarisspecialist op aanvraag Begeleiding bij omzetting naar een vof of bv op aanvraag Spoedtoeslag als je stukken na de 10e van de maand na het kwartaal aanlevert €50 per aangifte"},
{"id":"tarieven#183","groep":"Website","titel":"Tarieven: Goed om te weten","bron":"/tarieven","tags":"","tekst":"Waarom tot 100 transacties? Vrijwel elke dienstverlenende zzp’er blijft daar ruim onder. Zo betaalt bijna iedereen dezelfde prijs. Heb je structureel meer transacties, bijvoorbeeld met een webshop? Dan maken we een prijs op maat. Hoe werkt het maandelijkse 1-op-1 gesprek? Je plant het zelf in via onze online agenda, op een moment dat jou uitkomt. Het gesprek duurt maximaal 30 minuten, telefonisch of via video. We bespreken je cijfers, je vragen en wat eraan komt. Je hoeft het niet te gebruiken; het kan elke maand. Ik gebruik de kleineondernemersregeling (KOR). Wat betaal ik dan? Met de KOR kun je de btw op onze factuur niet terugvragen. Je betaalt dan €96,80 per maand, inclusief btw. Wanneer betaal ik? Je ontvangt aan het begin van elke maand een factuur. Die betaal je via de betaallink in de factuur, of automatisch via een incasso. Wat jij het handigst vindt."},
{"id":"tarieven#184","groep":"Website","titel":"Tarieven: Goed om te weten","bron":"/tarieven","tags":"","tekst":"Wat als ik niet tevreden ben? Ben je na je eerste maand niet tevreden? Laat het ons binnen die maand weten, dan krijg je het maandbedrag van je eerste maand terug en stopt de samenwerking. Zonder vragen en zonder gedoe. Kan ik opzeggen? Je betaalt per maand en je kunt maandelijks opzeggen. Stop je binnen 12 maanden nadat we je aangifte inkomstenbelasting hebben gedaan? Dan rekenen we die aangifte apart af (€250)."},
{"id":"tarieven#185","groep":"Website","titel":"Tarieven: Benieuwd of het bij je past?","bron":"/tarieven","tags":"","tekst":"In een kennismaking van 20 minuten kijken we samen naar je administratie en weet je direct waar je aan toe bent. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"veelgestelde-vragen#186","groep":"Website","titel":"Veelgestelde vragen","bron":"/veelgestelde-vragen","tags":"","tekst":"Home /  Veelgestelde vragen Typ je vraag in je eigen woorden, bijvoorbeeld \"zit ik ergens aan vast?\", of kies hieronder een onderwerp."},
{"id":"veelgestelde-vragen#187","groep":"Website","titel":"Veelgestelde vragen: Aanleveren en MoneyMonk","bron":"/veelgestelde-vragen","tags":"","tekst":"9 vragen Hoe lever ik mijn bonnetjes en facturen aan? Wanneer moet ik aanleveren?"},
{"id":"veelgestelde-vragen#188","groep":"Website","titel":"Veelgestelde vragen: Btw","bron":"/veelgestelde-vragen","tags":"","tekst":"5 vragen Wanneer moet mijn btw-aangifte binnen zijn? Wie betaalt de btw aan de Belastingdienst?"},
{"id":"veelgestelde-vragen#189","groep":"Website","titel":"Veelgestelde vragen: Inkomstenbelasting en jaarafsluiting","bron":"/veelgestelde-vragen","tags":"","tekst":"4 vragen Doen jullie ook mijn aangifte inkomstenbelasting? Kunnen jullie ook de aangifte van mijn partner doen?"},
{"id":"veelgestelde-vragen#190","groep":"Website","titel":"Veelgestelde vragen: Privacy en veiligheid","bron":"/veelgestelde-vragen","tags":"","tekst":"4 vragen Is mijn informatie veilig? Wat doen jullie met mijn gegevens? ← Alle onderwerpen"},
{"id":"veelgestelde-vragen#191","groep":"Website","titel":"Veelgestelde vragen: Over ons en werkwijze","bron":"/veelgestelde-vragen","tags":"","tekst":"Wie zijn Avezaat & Evers? Avezaat & Evers is opgericht door Koen Avezaat en Daan Evers. We nemen de complete boekhouding van zzp’ers en eenmanszaken uit handen, voor één vaste prijs per maand. Voor wie zijn jullie er? Voor zzp’ers en eenmanszaken in heel Nederland, ook met een winkel, salon, webshop of personeel, die hun administratie volledig uit handen willen geven. Heb je een vof of bv? Dan zijn we op dit moment niet de juiste partij. Ik heb een eenmanszaak, maar zie mezelf niet als zzp’er. Zijn jullie er ook voor mij? Zeker. Of je nu freelancer bent of een winkel, salon, webshop of vaste opdrachtgevers hebt: heb je een eenmanszaak, dan ben je bij ons aan het goede adres. Je krijgt hetzelfde pakket voor dezelfde prijs. Heb je veel transacties, bijvoorbeeld door losse pinbetalingen of een webshop? Dan maken we een prijs op maat. Ik heb personeel."},
{"id":"veelgestelde-vragen#192","groep":"Website","titel":"Veelgestelde vragen: Over ons en werkwijze","bron":"/veelgestelde-vragen","tags":"","tekst":"Kunnen jullie de lonen doen? Heb je personeel? Dan regelen we de loonadministratie samen met een salarisspecialist. Wij verwerken de loonkosten in je boekhouding, zodat je voor de rest één aanspreekpunt houdt. Bespreek het gerust in de kennismaking. Helpen jullie ook een vof of bv? Nee, op dit moment niet. We richten ons volledig op eenmanszaken en zzp’ers, zodat we die heel goed kunnen bedienen. Bij een vof of bv komt er meer bij kijken, zoals een winstverdeling tussen vennoten of een aparte aangifte vennootschapsbelasting. Overweeg je om van je eenmanszaak een vof of bv te maken? Dan denken we graag met je mee over het juiste moment. Wat bedoelen jullie met 'je eigen boekhouder'? Je hebt altijd contact met dezelfde vaste boekhouder, die jouw bedrijf door en door kent. Geen wisselende medewerkers en je hoeft nooit opnieuw je verhaal te doen."},
{"id":"veelgestelde-vragen#193","groep":"Website","titel":"Veelgestelde vragen: Over ons en werkwijze","bron":"/veelgestelde-vragen","tags":"","tekst":"Wat moet ik zelf nog doen? Alleen je bonnetjes, inkoopfacturen en verkoopfacturen aanleveren via de app of per mail. Het boeken, controleren en de aangiftes doen wij. Werken jullie alleen online? Ja. We werken volledig online, voor ondernemers in heel Nederland. Contact gaat via telefoon, mail, WhatsApp en videobellen. Met welk boekhoudprogramma werken jullie? Met MoneyMonk. De software en de app zitten in je pakket. Lees hoe je start in onze handleiding Van start met MoneyMonk . Wat als jullie een fout maken? Dan lossen we het op, zonder extra kosten voor jou. We corrigeren de boeking of aangifte en laten je precies weten wat er is gebeurd. Ontstaat er toch schade door een fout van ons, dan zijn we daarvoor verzekerd met een beroepsaansprakelijkheidsverzekering."},
{"id":"veelgestelde-vragen#194","groep":"Website","titel":"Veelgestelde vragen: Tarieven en contract","bron":"/veelgestelde-vragen","tags":"","tekst":"Wat kost het? €80 per maand excl. btw (€96,80 incl. btw), tot 100 banktransacties per maand. Daarin zit je boekhouding, vier btw-aangiftes, je aangifte inkomstenbelasting, je jaarcijfers, de software en elke maand een 1-op-1 gesprek. Zie alle tarieven . Wat telt als een banktransactie? Elke bij- of afschrijving op je zakelijke rekening(en). Een betaling van een klant is er één, net als een pinbetaling in de winkel. Wat als ik meer dan 100 transacties per maand heb? Dan maken we een prijs op maat, bijvoorbeeld als je een webshop hebt. Zit je af en toe een maandje boven de 100? Geen probleem; het gaat om je structurele aantal. Zijn er kosten buiten het pakket? Alleen als je ze nodig hebt: ICP-aangifte bij klanten binnen de EU (€15 p/m), IB-aangifte voor je fiscaal partner (€150 per jaar), overstappen (€149 eenmalig) en achterstallige administratie (€60 per uur)."},
{"id":"veelgestelde-vragen#195","groep":"Website","titel":"Veelgestelde vragen: Tarieven en contract","bron":"/veelgestelde-vragen","tags":"","tekst":"We spreken dit altijd vooraf af. Kan ik opzeggen? Ja, maandelijks. Stop je binnen 12 maanden nadat we je aangifte inkomstenbelasting hebben gedaan, dan rekenen we die aangifte apart af (€250). Wat als ik niet tevreden ben? Ben je na je eerste maand niet tevreden? Laat het ons binnen die maand weten, dan krijg je het maandbedrag van je eerste maand terug en stopt de samenwerking. Zonder vragen en zonder gedoe. Hoe betaal ik? Je ontvangt aan het begin van elke maand een factuur. Die betaal je via de betaallink in de factuur, of automatisch via een incasso. Wat jij het handigst vindt. Ik gebruik de KOR. Wat betaal ik dan? Met de kleineondernemersregeling kun je de btw op onze factuur niet terugvragen. Je betaalt dan €96,80 per maand, inclusief btw. Zijn de kosten van een boekhouder aftrekbaar? Ja. Het zijn zakelijke kosten, dus ze verlagen je winst."},
{"id":"veelgestelde-vragen#196","groep":"Website","titel":"Veelgestelde vragen: Tarieven en contract","bron":"/veelgestelde-vragen","tags":"","tekst":"Ben je btw-plichtig, dan vraag je ook de btw op onze factuur terug. Krijg ik iets als ik jullie aanbeveel? Ja. Wordt een collega via jou klant, dan krijgen jullie allebei een maand gratis boekhouding (€80 excl. btw). We verrekenen die op de eerstvolgende factuur zodra je collega drie maanden klant is. Lees alles op onze pagina Aanbevelen . Ik kom via een collega. Krijg ik korting? Ja, als je collega al klant bij ons is. Noem zijn of haar naam bij het plannen van de kennismaking of in het gesprek. Ben je drie maanden klant, dan krijgen jullie allebei een maand gratis."},
{"id":"veelgestelde-vragen#197","groep":"Website","titel":"Veelgestelde vragen: Starten en overstappen","bron":"/veelgestelde-vragen","tags":"","tekst":"Hoe word ik klant? Plan een gratis kennismaking van 20 minuten. Past het, dan ontvang je een opdrachtbevestiging. Daarna richten wij je administratie in en krijg je een uitnodiging voor MoneyMonk. Wat gebeurt er na de kennismaking? Je krijgt meteen een persoonlijke bevestiging van ons. Binnen 24 uur na het gesprek sturen we je een voorstel op maat: wat je betaalt, eventuele extra’s en per wanneer we starten. Je zit nergens aan vast. Zeg je ja, dan regelen wij de rest: je MoneyMonk-account, de machtiging voor je aangiftes en, als je overstapt, de overdracht met je oude boekhouder. In je eerste maand plannen we samen je eerste 1-op-1 . Wat kost overstappen? Eenmalig €149 voor het inrichten en de overdracht. Stap je over per 1 januari en meld je je aan uiterlijk 15 december? Dan is overstappen gratis."},
{"id":"veelgestelde-vragen#198","groep":"Website","titel":"Veelgestelde vragen: Starten en overstappen","bron":"/veelgestelde-vragen","tags":"","tekst":"Wanneer kan ik het beste overstappen? Het meest overzichtelijk is per 1 januari, bij het begin van een nieuw boekjaar. Overstappen aan het begin van een kwartaal kan ook. Lees meer in Overstappen van boekhouder: waar let je op? Moet ik zelf mijn oude boekhouder regelen? Alleen opzeggen. De overdracht van gegevens, zoals je laatste aangiftes en je eindbalans, regelen wij. Mijn administratie loopt achter. Kunnen jullie helpen? Ja. We maken vooraf een prijsafspraak voor het inhalen van de achterstand (€60 per uur), zodat je weet waar je aan toe bent. Ik ben net gestart. Kan ik meteen beginnen? Zeker. We richten je administratie vanaf je startdatum in. Lees ook onze pagina voor starters . Ik heb nog weinig omzet. Loont een boekhouder dan? Reken het even na: een zzp’er rekent gemiddeld €83 per uur (bron: Knab ). Ben je meer dan een uur per maand met je administratie bezig, dan kost dat je al meer dan ons pakket. In de kennismaking rekenen we het voor jouw situatie uit."},
{"id":"veelgestelde-vragen#199","groep":"Website","titel":"Veelgestelde vragen: Aanleveren en MoneyMonk","bron":"/veelgestelde-vragen","tags":"","tekst":"Hoe lever ik mijn bonnetjes en facturen aan? Maak een foto in de MoneyMonk-app, stuur je factuur door per mail of upload hem op je computer. Je banktransacties komen automatisch binnen via de bankkoppeling. Welke banken kan ik koppelen? De gratis automatische bankkoppeling in MoneyMonk werkt met onder meer ABN AMRO, ING, Rabobank, bunq, Knab, ASN Bank, SNS, RegioBank, Triodos en N26. Mollie kun je ook direct koppelen. Revolut, Wise, PayPal en Stripe koppel je automatisch via Ponto, een koppeldienst die MoneyMonk daarvoor gebruikt. Je kunt je transacties ook als bestand (CSV of MT940) downloaden en in MoneyMonk zetten. We helpen je bij de start om de handigste manier te kiezen. Wanneer moet ik aanleveren? Het liefst binnen een paar dagen. De harde deadline is de 10e na afloop van elk kwartaal, zodat wij je btw-aangifte op tijd kunnen indienen."},
{"id":"veelgestelde-vragen#200","groep":"Website","titel":"Veelgestelde vragen: Aanleveren en MoneyMonk","bron":"/veelgestelde-vragen","tags":"","tekst":"Wat als ik te laat aanlever? Dan kunnen we niet garanderen dat je aangifte op tijd is. Lukt het ons met spoed, dan rekenen we €50 per aangifte. Laat het ons zo vroeg mogelijk weten als je later bent. Moet ik mijn facturen in MoneyMonk maken? Nee, dat mag maar het hoeft niet. Maak je ze elders, lever ze dan aan zoals een inkoopfactuur. Facturen uit MoneyMonk staan wel meteen in je administratie. Ik ben een bonnetje kwijt. Wat nu? Vraag de leverancier om een kopie, of zoek de factuur op in je mail of in je account bij de webshop. Lukt dat niet, laat het ons weten. Ik heb iets privé betaald met mijn zakelijke rekening. Geen probleem, dat gebeurt iedereen. Zet er een notitie bij in MoneyMonk of laat het ons weten, dan boeken we het als privé. Kan ik mijn uren en kilometers bijhouden? Ja."},
{"id":"veelgestelde-vragen#201","groep":"Website","titel":"Veelgestelde vragen: Aanleveren en MoneyMonk","bron":"/veelgestelde-vragen","tags":"","tekst":"Met de module voor uren- en rittenregistratie in MoneyMonk houd je je gewerkte uren en zakelijke kilometers bij. Handig voor het urencriterium en je kilometervergoeding. Deze zit gewoon in je pakket. Hoe lang moet ik mijn administratie bewaren? In principe 7 jaar. Wat je in MoneyMonk aanlevert, wordt digitaal bewaard. Lees meer in Welke bonnetjes moet je bewaren?"},
{"id":"veelgestelde-vragen#202","groep":"Website","titel":"Veelgestelde vragen: Btw","bron":"/veelgestelde-vragen","tags":"","tekst":"Wanneer moet mijn btw-aangifte binnen zijn? Per kwartaal, uiterlijk op de laatste dag van de maand erna: 30 april, 31 juli, 31 oktober en 31 januari. Wij dienen hem voor je in. Meer in Btw-aangifte: deadlines . Wie betaalt de btw aan de Belastingdienst? Wij doen de aangifte, jij maakt het bedrag over naar de Belastingdienst. Het geld gaat dus nooit via ons. Wanneer hoor ik hoeveel btw ik moet betalen? Na het verwerken van het kwartaal sturen we je vóór de deadline een overzicht met het bedrag. Zo kom je niet voor verrassingen te staan. Ik heb klanten in het buitenland. Kunnen jullie dat ook? Ja. Voor klanten binnen de EU is vaak een ICP-aangifte nodig; die verzorgen we voor €15 per maand extra. Klanten buiten de EU bespreken we in de kennismaking. Ik gebruik de kleineondernemersregeling (KOR). Moet ik dan nog aangifte doen? Met de KOR reken je geen btw en hoef je in principe geen btw-aangifte te doen. Of de KOR voor jou gunstig is, rekenen we graag met je door."},
{"id":"veelgestelde-vragen#203","groep":"Website","titel":"Veelgestelde vragen: Inkomstenbelasting en jaarafsluiting","bron":"/veelgestelde-vragen","tags":"","tekst":"Doen jullie ook mijn aangifte inkomstenbelasting? Ja, die zit in je pakket. We maken ook je jaarcijfers: de winst- en verliesrekening en de balans. Kunnen jullie ook de aangifte van mijn partner doen? Ja, voor €150 per jaar. Dat is vaak slim, omdat je bepaalde posten tussen fiscale partners kunt verdelen. Krijg ik de aftrekposten waar ik recht op heb? We kijken bij elke aangifte naar de ondernemersaftrekken, zoals de zelfstandigenaftrek en de startersaftrek. Voor de zelfstandigenaftrek moet je onder meer aan het urencriterium van 1.225 uur per jaar voldoen; houd je uren dus bij. Wanneer doen jullie mijn aangifte inkomstenbelasting? In het voorjaar na afloop van het jaar, zodra je administratie compleet is. Waar nodig vragen we uitstel aan, zodat er geen haast ontstaat."},
{"id":"veelgestelde-vragen#204","groep":"Website","titel":"Veelgestelde vragen: Bereikbaarheid en het maandelijkse gesprek","bron":"/veelgestelde-vragen","tags":"","tekst":"Hoe bereik ik mijn boekhouder? Via WhatsApp, telefoon of mail. Je appt of belt direct met je eigen vaste boekhouder, niet met een algemene servicedesk. Hoe snel reageren jullie? Binnen 2 uur heb je een reactie van je eigen boekhouder, via WhatsApp, mail of telefoon. Hoe werkt het maandelijkse 1-op-1 gesprek? Je plant het zelf in via onze online agenda. Het duurt maximaal 30 minuten, telefonisch of via video. We bespreken je cijfers en je vragen. Het is een aanbod, geen verplichting. Wat als mijn boekhouder op vakantie of ziek is? Dan neemt de ander het over. Koen en Daan kennen elkaars klanten en werken in dezelfde administratie, dus je hoeft je verhaal niet opnieuw te doen en deadlines lopen nooit gevaar. Je weet vooraf bij wie je terechtkunt. Kost het extra als ik een vraag stel? Nee. Vragen stellen per mail, telefoon of WhatsApp is altijd inbegrepen. Geen rekening per telefoontje."},
{"id":"veelgestelde-vragen#205","groep":"Website","titel":"Veelgestelde vragen: Privacy en veiligheid","bron":"/veelgestelde-vragen","tags":"","tekst":"Is mijn informatie veilig? Je administratie staat in MoneyMonk, een Nederlands boekhoudprogramma met een vergunning van De Nederlandsche Bank voor de bankkoppeling. Onze mail en documenten staan in Microsoft 365. Wij gebruiken tweestapsverificatie op onze accounts en delen je gegevens alleen waar dat nodig is, zoals bij je aangiftes. Wat doen jullie met mijn gegevens? We gebruiken ze alleen om je boekhouding en aangiftes te verzorgen en bewaren ze zolang de wet dat vraagt. Lees alles in onze privacyverklaring . Waarom vragen jullie om een identiteitsbewijs? Als boekhouder zijn we wettelijk verplicht om te controleren wie onze klanten zijn (de Wwft). Daarom vragen we bij de start om een geldig identiteitsbewijs. Wat gebeurt er met mijn administratie als ik opzeg? Je administratie is van jou. Je krijgt een export mee, zodat je die kunt overdragen aan een nieuwe boekhouder. Let op: je moet je administratie 7 jaar bewaren."},
{"id":"veelgestelde-vragen#206","groep":"Website","titel":"Veelgestelde vragen: Staat je vraag er niet bij?","bron":"/veelgestelde-vragen","tags":"","tekst":"Stel hem gerust. Mail, bel of app ons, of plan direct een vrijblijvende kennismaking. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"overstappen#207","groep":"Website","titel":"Overstappen van boekhouder? Wij regelen het.","bron":"/overstappen","tags":"","tekst":"Home / Overstappen  Ben je klaar met wisselende contactpersonen, onverwachte rekeningen of zelf boeken in een programma? Overstappen is minder werk dan je denkt. De overdracht met je vorige boekhouder nemen wij voor onze rekening. Plan een gratis kennismaking Bereken je prijs Vrijblijvend, 20 minuten, gewoon online Zo gaat je overstap Wij doen het werk Van Huidige boekhouder Naar Avezaat & Evers Opzeggen Eén mailtje, wij helpen met het moment Jij Gegevens opvragen Laatste aangiftes en eindbalans Wij Inrichten en bank koppelen Klaar voor het nieuwe boekjaar Wij Aanleveren via de app Vanaf nu doen wij de rest Jij Gratis overstappen per 1 januari bij aanmelding t/m 15 december"},
{"id":"overstappen#208","groep":"Website","titel":"Overstappen van boekhouder? Wij regelen het.: Kennismaken","bron":"/overstappen","tags":"","tekst":"We bespreken je situatie, je huidige boekhouder en het beste overstapmoment. Stap 2"},
{"id":"overstappen#209","groep":"Website","titel":"Overstappen van boekhouder? Wij regelen het.: Opzeggen","bron":"/overstappen","tags":"","tekst":"Je zegt op bij je huidige boekhouder. Check je opzegtermijn; wij helpen je met het juiste moment. Stap 3"},
{"id":"overstappen#210","groep":"Website","titel":"Overstappen van boekhouder? Wij regelen het.: Overdracht","bron":"/overstappen","tags":"","tekst":"Wij vragen de benodigde gegevens op, zoals je laatste aangiftes en eindbalans, en richten je administratie in. Stap 4"},
{"id":"overstappen#211","groep":"Website","titel":"Overstappen van boekhouder? Wij regelen het.: Klaar","bron":"/overstappen","tags":"","tekst":"Je bank is gekoppeld en je levert voortaan aan via de app. Vanaf nu doen wij de rest."},
{"id":"overstappen#212","groep":"Website","titel":"Overstappen van boekhouder? Wij regelen het.: Overstappen per 1 januari: zo ziet het eruit","bron":"/overstappen","tags":"","tekst":"De jaarwisseling is het rustigste moment om te wisselen. Je vorige boekhouder maakt het oude jaar af, wij beginnen met een schone lei. Meld je je aan uiterlijk 15 december, dan kost de overstap je niets. Je merkt er in de praktijk weinig van. Het enige wat voor jou verandert: vanaf januari maak je een foto van je bonnetje in de app, en je hebt één vaste boekhouder die je kunt appen. Nu tot 15 december Kennismaken en aanmelden. We bespreken je situatie en spreken af wie welke aangifte doet. December Je zegt op bij je huidige boekhouder per 31 december. Wij richten je administratie in en sturen je een uitnodiging voor de app. 1 januari Je bank is gekoppeld en je levert aan via de app. Vanaf nu boeken wij alles. Januari Je vorige boekhouder doet nog de btw-aangifte over het vierde kwartaal (uiterlijk 31 januari). Wij nemen de eindbalans over als beginbalans. April Wij doen je eerste btw-aangifte over het eerste kwartaal. De aangifte inkomstenbelasting over het oude jaar spreken we vooraf samen af."},
{"id":"overstappen#213","groep":"Website","titel":"Overstappen van boekhouder? Wij regelen het.: Waarom ondernemers naar ons overstappen","bron":"/overstappen","tags":"","tekst":"Dit horen we het vaakst als we vragen waarom iemand wil wisselen. En zo gaat het bij ons. Elke keer iemand anders aan de lijn Eén vaste boekhouder die je bedrijf kent Dagen wachten op antwoord Binnen 2 uur reactie, ook via WhatsApp Een rekening voor elke vraag Vragen stellen is altijd inbegrepen Onverwachte kosten aan het eind van het jaar Vaste prijs van €80 per maand, aangiftes inbegrepen Zelf boeken kost elke maand uren Jij maakt een foto, wij doen de rest Pas bij de aangifte horen hoe je ervoor staat Elke maand een 1-op-1 en altijd inzicht in de app"},
{"id":"overstappen#214","groep":"Website","titel":"Overstappen van boekhouder? Wij regelen het.: Wanneer kun je het beste overstappen?","bron":"/overstappen","tags":"","tekst":"Het meest overzichtelijke moment is per 1 januari: dan begint een nieuw boekjaar en is de verdeling helder. Je vorige boekhouder rondt het oude jaar af, wij starten met het nieuwe. Overstappen aan het begin van een kwartaal kan ook goed. Dan spreken we af wie welke aangifte doet, zodat er niets tussen wal en schip valt."},
{"id":"overstappen#215","groep":"Website","titel":"Overstappen van boekhouder? Wij regelen het.: Dit hebben we van je nodig","bron":"/overstappen","tags":"","tekst":"Je KvK-nummer en btw-identificatienummer De laatst ingediende btw-aangifte De aangifte inkomstenbelasting van vorig jaar De eindbalans van je vorige boekhouder Toegang tot je zakelijke bankrekening voor de koppeling Heb je dit niet allemaal paraat? Geen probleem, dan vragen wij het op. Je oude administratie blijft van jou. Vraag je vorige boekhouder om een export, want je moet je administratie 7 jaar bewaren. Wij nemen de eindbalans over, zodat je cijfers naadloos doorlopen."},
{"id":"overstappen#216","groep":"Website","titel":"Overstappen van boekhouder? Wij regelen het.: Vragen over overstappen","bron":"/overstappen","tags":"","tekst":"Wat kost overstappen? Eenmalig €149 voor het inrichten en de overdracht. Stap je over per 1 januari en meld je je aan uiterlijk 15 december? Dan is overstappen gratis. Moet ik zelf contact opnemen met mijn vorige boekhouder? Alleen om op te zeggen. De overdracht van gegevens regelen wij. Ik boek nu zelf in een programma. Kan ik ook overstappen? Zeker. Je stopt met zelf boeken en levert voortaan alleen aan. We nemen je gegevens over en zetten alles over naar onze software. Mijn administratie loopt achter. Is dat een probleem? Nee, maar we maken wel vooraf een prijsafspraak voor het inhalen van de achterstand (€60 per uur). Zo weet je waar je aan toe bent. Kan ik ook halverwege het jaar overstappen? Ja. Het liefst aan het begin van een kwartaal, zodat de btw-aangiftes netjes verdeeld zijn. Je vorige boekhouder doet dan het lopende kwartaal af, wij nemen het daarna over."},
{"id":"overstappen#217","groep":"Website","titel":"Overstappen van boekhouder? Wij regelen het.: Vragen over overstappen","bron":"/overstappen","tags":"","tekst":"Aan het eind van het jaar maken wij je jaarcijfers en aangifte inkomstenbelasting. Wie doet de aangifte inkomstenbelasting over het oude jaar? Dat spreken we vooraf af. Vaak rondt je vorige boekhouder het oude jaar af, inclusief de jaarcijfers. Wil je dat wij die aangifte ook doen? Dan bespreken we dat in de kennismaking. Raak ik gegevens kwijt bij de overstap? Nee. We nemen de eindbalans van je vorige boekhouder over als beginbalans, en je oude administratie krijg je als export mee. Zo lopen je cijfers gewoon door."},
{"id":"overstappen#218","groep":"Website","titel":"Overstappen van boekhouder? Wij regelen het.: Per 1 januari bij ons beginnen?","bron":"/overstappen","tags":"","tekst":"Plan nu een kennismaking. Dan heb je voor de jaarwisseling alles geregeld. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"starters#219","groep":"Website","titel":"Net begonnen als zzp’er?","bron":"/starters","tags":"","tekst":"Home / Starters  Je hebt je ingeschreven bij de KvK en je eerste opdracht binnen. Nu de administratie nog. Wij zetten het vanaf dag één goed op, zodat je je kunt richten op je klanten. Plan een gratis kennismaking Bereken je prijs Vrijblijvend, 20 minuten, gewoon online Jouw start, goed geregeld Vanaf dag één Administratie ingericht in MoneyMonk Software en app zitten in je pakket Zakelijke rekening gekoppeld Transacties komen vanzelf binnen Btw-aangifte elk kwartaal op tijd Je weet vooraf wat je betaalt Weten wat je opzij moet zetten Voor btw en inkomstenbelasting Aangifte inkomstenbelasting Inclusief je ondernemersaftrek Eerstvolgende btw-deadline: 31 oktober"},
{"id":"starters#220","groep":"Website","titel":"Net begonnen als zzp’er?: \"Welke bonnetjes moet ik bewaren?\"","bron":"/starters","tags":"","tekst":"Alles wat zakelijk is, en je moet het jarenlang kunnen laten zien. Met de app maak je een foto, wij verwerken en bewaren het voor je."},
{"id":"starters#221","groep":"Website","titel":"Net begonnen als zzp’er?: \"Wanneer moet ik btw betalen?\"","bron":"/starters","tags":"","tekst":"Vier keer per jaar, met vaste deadlines. Wij houden ze bij en sturen je op tijd een seintje over het bedrag."},
{"id":"starters#222","groep":"Website","titel":"Net begonnen als zzp’er?: \"Hoeveel moet ik opzij zetten?\"","bron":"/starters","tags":"","tekst":"Je ziet in de app wat je verdient. In de kennismaking geven we je een richtlijn voor wat je apart zet voor belastingen."},
{"id":"starters#223","groep":"Website","titel":"Net begonnen als zzp’er?: Administratie inrichten","bron":"/starters","tags":"","tekst":"We richten je boekhouding in, koppelen je zakelijke rekening en laten je zien hoe je in de app facturen maakt en bonnetjes aanlevert. Doorlopend"},
{"id":"starters#224","groep":"Website","titel":"Net begonnen als zzp’er?: Boekhouding en btw","bron":"/starters","tags":"","tekst":"Elk kwartaal verwerken we je administratie en dienen we je btw-aangifte in. Jij krijgt vooraf te zien wat je moet betalen. Jaarlijks"},
{"id":"starters#225","groep":"Website","titel":"Net begonnen als zzp’er?: Aangifte inkomstenbelasting","bron":"/starters","tags":"","tekst":"We doen je aangifte en kijken naar de ondernemersaftrekken waar je als starter mogelijk recht op hebt, zoals de startersaftrek."},
{"id":"starters#226","groep":"Website","titel":"Net begonnen als zzp’er?: Ook als starter: €80 per maand, alles inbegrepen","bron":"/starters","tags":"","tekst":"Geen apart starterspakket met beperkingen. Je krijgt meteen alles: je eigen boekhouder, btw- en IB-aangifte, en elke maand een 1-op-1 gesprek. Juist in je eerste jaar heb je daar veel aan. Plan een kennismaking"},
{"id":"starters#227","groep":"Website","titel":"Net begonnen als zzp’er?: Tip: begin goed","bron":"/starters","tags":"","tekst":"Open een aparte zakelijke rekening. Bewaar elk zakelijk bonnetje vanaf dag één. Zet een vast percentage van elke factuur apart. Houd je uren bij als je voor de zelfstandigenaftrek in aanmerking wilt komen. Lees: welke bonnetjes moet je bewaren?"},
{"id":"starters#228","groep":"Website","titel":"Net begonnen als zzp’er?: Belangrijke deadlines voor starters","bron":"/starters","tags":"","tekst":"Als ondernemer krijg je vaste momenten waarop je aangifte doet en betaalt. Mis je er een, dan kan de Belastingdienst een boete opleggen. Dit zijn de data die elk jaar terugkomen. Bij ons hoef je ze niet te onthouden: jij levert aan vóór de 10e na elk kwartaal, wij dienen op tijd in en laten je vooraf weten wat je betaalt. 30 april Btw-aangifte 1e kwartaal Over januari tot en met maart. 1 mei Aangifte inkomstenbelasting Over het vorige jaar. Via ons kun je vaak uitstel krijgen, maar begin op tijd. 31 juli Btw-aangifte 2e kwartaal Over april tot en met juni. 31 oktober Btw-aangifte 3e kwartaal Over juli tot en met september. 31 januari Btw-aangifte 4e kwartaal Over oktober tot en met december. Alles over de btw-aangifte en deadlines Zet alle deadlines in je agenda Btw-aangifte, aangifte inkomstenbelasting, KOR en jaareinde. Je krijgt een week van tevoren een herinnering, en de agenda werkt zich vanzelf bij. Gratis. iPhone of Mac Google Agenda Outlook Download"},
{"id":"starters#229","groep":"Website","titel":"Net begonnen als zzp’er?: Vragen van starters","bron":"/starters","tags":"","tekst":"Ik heb nog maar weinig omzet. Is een boekhouder dan de moeite waard? Reken het even na. Een zzp’er rekent gemiddeld €83 per uur. 1 Ben je meer dan een uur per maand met je administratie bezig, dan kost dat je al meer tijd dan ons pakket van €80 per maand. Daarbij zijn de kosten van een boekhouder aftrekbaar, mis je geen aftrekposten en voorkom je boetes. Twijfel je? In de kennismaking rekenen we het samen voor jouw situatie uit. 1. Gemiddeld uurtarief excl. btw volgens onderzoek van Knab onder ruim 20.000 zelfstandigen (2026). Bron: Knab . Kunnen jullie helpen bij mijn inschrijving bij de KvK? De inschrijving doe je zelf bij de KvK. We denken graag mee over keuzes die je daarbij maakt, zoals je btw-situatie. Ik ben gestart halverwege het jaar. Kan ik nu nog instappen? Ja. We verwerken je administratie vanaf je startdatum. Heb je al een paar maanden zonder administratie gewerkt? Dan maken we vooraf een prijsafspraak voor het inhalen."},
{"id":"starters#230","groep":"Website","titel":"Net begonnen als zzp’er?: Begin goed, vanaf dag één","bron":"/starters","tags":"","tekst":"Plan een gratis kennismaking van 20 minuten en weet direct waar je aan toe bent. Plan een gratis kennismaking Of neem contact op: Mail Bel WhatsApp"},
{"id":"voorwaarden#231","groep":"Website","titel":"Algemene voorwaarden","bron":"/voorwaarden","tags":"","tekst":"Versie 1.0, vastgesteld op 28 oktober 2026. Deze voorwaarden gelden voor zakelijke opdrachtgevers."},
{"id":"voorwaarden#232","groep":"Website","titel":"Algemene voorwaarden: Artikel 1. Definities","bron":"/voorwaarden","tags":"","tekst":"In deze algemene voorwaarden wordt verstaan onder: Avezaat & Evers: de vennootschap onder firma Avezaat & Evers, gevestigd te Rotterdamseweg 26, 2921 AP Krimpen aan den IJssel, ingeschreven bij de Kamer van Koophandel onder nummer 42133742, btw-nummer NL869872862B01, e-mail info@avezaatenevers.nl , telefoon (085) 060 43 63. Opdrachtgever: de natuurlijke persoon of rechtspersoon die handelt in de uitoefening van een beroep of bedrijf en met Avezaat & Evers een overeenkomst sluit of wil sluiten. Opdracht: de werkzaamheden die Avezaat & Evers voor Opdrachtgever verricht, zoals vastgelegd in de Opdrachtbevestiging. Opdrachtbevestiging: het document of de e-mail waarin Avezaat & Evers de Opdracht, de Vergoeding, de ingangsdatum en de overige afspraken per Opdrachtgever vastlegt, met het model uit bijlage 1."},
{"id":"voorwaarden#233","groep":"Website","titel":"Algemene voorwaarden: Artikel 1. Definities","bron":"/voorwaarden","tags":"","tekst":"Overeenkomst: de overeenkomst tussen Avezaat & Evers en Opdrachtgever, bestaande uit de Opdrachtbevestiging en deze algemene voorwaarden. Vergoeding: het bedrag dat Opdrachtgever per maand verschuldigd is voor de Opdracht, zoals genoemd in de Opdrachtbevestiging. Stukken: alle bescheiden en gegevens die Opdrachtgever aan Avezaat & Evers verstrekt, zoals facturen, bonnetjes, bankafschriften en loongegevens. Software: de boekhoudsoftware MoneyMonk en eventuele andere programma’s die Avezaat & Evers gebruikt. Portaal: het systeem van Avezaat & Evers waarmee zij de MoneyMonk-accounts van haar opdrachtgevers beheert. Schriftelijk: op papier of op een duurzame gegevensdrager, zoals e-mail."},
{"id":"voorwaarden#234","groep":"Website","titel":"Algemene voorwaarden: Artikel 2. Toepasselijkheid en totstandkoming","bron":"/voorwaarden","tags":"","tekst":"2.1 Deze algemene voorwaarden gelden voor alle aanbiedingen, offertes, opdrachten en overeenkomsten van Avezaat & Evers en voor alle werkzaamheden die daaruit voortvloeien, ook als Avezaat & Evers derden inschakelt. 2.2 Afwijkingen van deze voorwaarden gelden alleen als ze Schriftelijk zijn overeengekomen, bijvoorbeeld in de Opdrachtbevestiging. Gaat de Opdrachtbevestiging in tegen de algemene voorwaarden, dan gaat de Opdrachtbevestiging voor. 2.3 Algemene voorwaarden van Opdrachtgever zijn niet van toepassing, ook niet als Opdrachtgever daar in een opdracht of bevestiging naar verwijst, tenzij Avezaat & Evers die uitdrukkelijk en Schriftelijk heeft aanvaard. 2.4 De Overeenkomst komt tot stand op het moment dat Opdrachtgever de Opdrachtbevestiging Schriftelijk of per e-mail aanvaardt, of op het moment dat Avezaat & Evers met instemming van Opdrachtgever met de uitvoering begint."},
{"id":"voorwaarden#235","groep":"Website","titel":"Algemene voorwaarden: Artikel 2. Toepasselijkheid en totstandkoming","bron":"/voorwaarden","tags":"","tekst":"Een handtekening is niet vereist. 2.5 Avezaat & Evers stelt deze algemene voorwaarden voor of bij het sluiten van de Overeenkomst ter hand aan Opdrachtgever, bijvoorbeeld als bijlage bij de Opdrachtbevestiging of via een link. Gebeurt dat elektronisch, dan stelt Avezaat & Evers de voorwaarden zo beschikbaar dat Opdrachtgever ze kan opslaan en later kan raadplegen. Zijn de voorwaarden gedeponeerd, dan vermeldt Avezaat & Evers waar en dat ze op verzoek kosteloos worden toegezonden. 2.6 Avezaat & Evers mag een Opdrachtgever weigeren, bijvoorbeeld bij een onvoldoende zekerheid dat de Opdracht goed kan worden uitgevoerd of bij een eerder betalingsprobleem. 2.7 Is Opdrachtgever een natuurlijk persoon die niet handelt in de uitoefening van een beroep of bedrijf (een consument), dan zijn deze voorwaarden niet van toepassing. Opdrachtgever meldt dit vooraf aan Avezaat & Evers."},
{"id":"voorwaarden#236","groep":"Website","titel":"Algemene voorwaarden: Artikel 3. Opdracht en uitvoering","bron":"/voorwaarden","tags":"","tekst":"3.1 Avezaat & Evers voert voor Opdrachtgever de werkzaamheden uit die in de Opdrachtbevestiging zijn aangekruist. Dat kunnen de volgende werkzaamheden zijn: Boekhouding: het verwerken van inkoop- en verkoopfacturen en bankboekingen, het afstemmen van de bankrekening, periodieke overzichten en de jaarafsluiting in MoneyMonk. Omzetbelasting: het opstellen en indienen van de btw-aangifte per maand, kwartaal of jaar, zoals vermeld in de Opdrachtbevestiging. Inkomstenbelasting: het opstellen en indienen van de aangifte inkomstenbelasting van Opdrachtgever over het in de Opdrachtbevestiging genoemde jaar. Alleen de aangekruiste werkzaamheden vallen onder de Opdracht."},
{"id":"voorwaarden#237","groep":"Website","titel":"Algemene voorwaarden: Artikel 3. Opdracht en uitvoering","bron":"/voorwaarden","tags":"","tekst":"3.2 Niet onder de Opdracht vallen, tenzij Schriftelijk anders overeengekomen: belastingadvies, aangiftes of werkzaamheden voor andere belastingen of personen dan hierboven genoemd (zoals vennootschapsbelasting, loonaangiftes of de aangifte van een partner), het opstellen van een jaarrekening, controle- of beoordelingswerkzaamheden, het herstellen van achterstanden uit eerdere jaren, bezwaar- of beroepsprocedures en het voeren van gesprekken met de Belastingdienst. 3.3 Avezaat & Evers voert de Opdracht uit naar beste inzicht en vermogen en met de zorg van een goed opdrachtnemer. Zij is niet verplicht een bepaald resultaat te bereiken, zoals een bepaald belastingvoordeel of een bepaalde terugbetaling. 3.4 Avezaat & Evers mag de Opdracht, of onderdelen daarvan, door derden laten uitvoeren (zoals een mede-vennoot of een ingehuurde kracht), onder haar verantwoordelijkheid."},
{"id":"voorwaarden#238","groep":"Website","titel":"Algemene voorwaarden: Artikel 3. Opdracht en uitvoering","bron":"/voorwaarden","tags":"","tekst":"3.5 Wil Opdrachtgever werkzaamheden laten uitvoeren die buiten de Opdracht vallen, dan maken partijen daarover vooraf afspraken over de werkzaamheden en de prijs, Schriftelijk of per e-mail. Zonder zo’n afspraak brengt Avezaat & Evers de extra uren in rekening tegen het uurtarief uit de Opdrachtbevestiging. 3.6 Avezaat & Evers verricht de Opdracht binnen de termijnen die in de Overeenkomst of in de wet zijn genoemd, voor zover Opdrachtgever de Stukken tijdig en volledig heeft aangeleverd (zie artikel 4). Genoemde termijnen zijn streeftermijnen, tenzij ze Schriftelijk als fatale termijn zijn overeengekomen of de wet een fatale termijn stelt. 3.7 Avezaat & Evers dient aangiftes pas in nadat Opdrachtgever daarmee heeft ingestemd, tenzij Avezaat & Evers de aangifte om een wettelijke termijn te halen moet indienen en Opdrachtgever daarop niet tijdig heeft gereageerd. Opdrachtgever blijft zelf verantwoordelijk voor de inhoud van de aangifte."},
{"id":"voorwaarden#239","groep":"Website","titel":"Algemene voorwaarden: Artikel 4. Verplichtingen van de opdrachtgever","bron":"/voorwaarden","tags":"","tekst":"4.1 Opdrachtgever levert de Stukken tijdig, volledig en in een bruikbare vorm aan. Voor de btw-aangifte is dat uiterlijk op de 10e dag van de maand na afloop van het tijdvak waarover de aangifte gaat, en voor de aangifte inkomstenbelasting uiterlijk 30 dagen vóór de wettelijke indieningsdatum of, bij verleend uitstel, vóór de verlengde datum. Afwijkende termijnen kunnen in de Opdrachtbevestiging staan. 4.2 Opdrachtgever verstrekt alle informatie die redelijkerwijs nodig is voor een goede uitvoering van de Opdracht, ook als Avezaat & Evers daar niet om vraagt, en meldt wijzigingen in zijn situatie direct, zoals een verhuizing, een wijziging van de rechtsvorm, het starten of stoppen van activiteiten of een wijziging van zijn btw-status. 4.3 Opdrachtgever staat in voor de juistheid en volledigheid van de Stukken."},
{"id":"voorwaarden#240","groep":"Website","titel":"Algemene voorwaarden: Artikel 4. Verplichtingen van de opdrachtgever","bron":"/voorwaarden","tags":"","tekst":"Avezaat & Evers is niet verplicht de juistheid of volledigheid van de Stukken te controleren, tenzij uit de aard van de Opdracht anders volgt. 4.4 Opdrachtgever zorgt dat Avezaat & Evers toegang heeft tot de benodigde bankgegevens en overige systemen, en geeft haar waar nodig een machtiging bij de Belastingdienst. Opdrachtgever blijft zelf verantwoordelijk voor zijn inloggegevens en machtigingen. 4.5 Levert Opdrachtgever de Stukken of informatie niet, niet tijdig of niet volledig aan, dan gelden de volgende gevolgen: Avezaat & Evers is niet aansprakelijk voor te late of onjuiste aangiftes, boetes, naheffingen of rente die daardoor ontstaan. Avezaat & Evers mag de werkzaamheden opschorten totdat de Stukken zijn aangeleverd. Avezaat & Evers mag de extra uren die nodig zijn om de achterstand weg te werken in rekening brengen tegen het uurtarief uit de Opdrachtbevestiging."},
{"id":"voorwaarden#241","groep":"Website","titel":"Algemene voorwaarden: Artikel 4. Verplichtingen van de opdrachtgever","bron":"/voorwaarden","tags":"","tekst":"De Vergoeding blijft ongewijzigd verschuldigd. 4.6 Opdrachtgever blijft zelf verantwoordelijk voor zijn wettelijke verplichtingen als ondernemer, zoals het bewaren van zijn administratie en het tijdig betalen van belastingen aan de Belastingdienst. 4.7 Opdrachtgever stuurt post van de Belastingdienst, zoals aanslagen, aanmaningen en brieven over een controle, binnen 5 werkdagen na ontvangst door aan Avezaat & Evers, voor zover Avezaat & Evers die post niet zelf ontvangt. Bezwaar of beroep tegen een beschikking valt niet onder de Opdracht (artikel 3.2); Opdrachtgever blijft zelf verantwoordelijk voor een tijdig bezwaar. Avezaat & Evers is niet aansprakelijk voor de gevolgen van post die Opdrachtgever niet of te laat doorstuurt."},
{"id":"voorwaarden#242","groep":"Website","titel":"Algemene voorwaarden: Artikel 4. Verplichtingen van de opdrachtgever","bron":"/voorwaarden","tags":"","tekst":"4.8 Avezaat & Evers kan op grond van de Wet ter voorkoming van witwassen en financieren van terrorisme (Wwft) verplicht zijn Opdrachtgever te identificeren en de herkomst van geldstromen vast te stellen. Opdrachtgever werkt daaraan mee, toont op verzoek een geldig identiteitsbewijs en beantwoordt vragen binnen redelijke tijd. Avezaat & Evers mag een ongebruikelijke transactie melden bij de FIU-Nederland, ook zonder dit aan Opdrachtgever te melden, en is daarvoor niet aansprakelijk. Werkt Opdrachtgever niet mee, of kan Avezaat & Evers anders niet aan de wet voldoen, dan mag zij de werkzaamheden opschorten of de Overeenkomst met onmiddellijke ingang beëindigen, zonder tot schadevergoeding verplicht te zijn."},
{"id":"voorwaarden#243","groep":"Website","titel":"Algemene voorwaarden: Artikel 5. Software en gegevens","bron":"/voorwaarden","tags":"","tekst":"5.1 Avezaat & Evers voert de Opdracht uit in MoneyMonk. De kosten van MoneyMonk zijn begrepen in de Vergoeding. Opdrachtgever betaalt daarvoor geen aparte kosten. 5.2 Opdrachtgever heeft een eigen MoneyMonk-account met een eigen administratie. Avezaat & Evers beheert dat account via haar Portaal. Opdrachtgever krijgt ook zelf toegang tot zijn administratie in MoneyMonk. Daar stuurt hij bonnen en facturen in en ziet hij een overzicht van zijn kosten en opbrengsten. Wil Opdrachtgever andere gebruikers toegang geven, dan meldt hij dat aan Avezaat & Evers. 5.3 De administratie en de gegevens daarin blijven eigendom van Opdrachtgever. Avezaat & Evers gebruikt de gegevens alleen voor de uitvoering van de Opdracht. 5.4 Avezaat & Evers is niet aansprakelijk voor storingen, onderhoud, wijzigingen of het beëindigen van software van derden, zoals MoneyMonk."},
{"id":"voorwaarden#244","groep":"Website","titel":"Algemene voorwaarden: Artikel 5. Software en gegevens","bron":"/voorwaarden","tags":"","tekst":"Treedt zo’n storing op, dan spant Avezaat & Evers zich in om de werkzaamheden zo snel mogelijk voort te zetten. Zie ook artikel 10.1 (overmacht). 5.5 Bij het einde van de Overeenkomst stelt Avezaat & Evers de administratie en de bijbehorende Stukken, voor zover nog in haar bezit, binnen 30 dagen na het einde ter beschikking aan Opdrachtgever in een gangbaar en leesbaar formaat, zoals een export uit MoneyMonk of PDF’s. Daarna beëindigt Avezaat & Evers haar beheer van het account van Opdrachtgever via het Portaal en draagt zij dat beheer, indien gewenst, over aan Opdrachtgever of aan een door Opdrachtgever aangewezen boekhouder. Avezaat & Evers mag de teruggave en de overdracht opschorten zolang openstaande facturen niet zijn betaald, voor zover de wet dat toelaat. 5.6 Avezaat & Evers mag kopieën van gegevens en stukken bewaren voor zover zij daartoe wettelijk verplicht is of om haar eigen werk aan te tonen."},
{"id":"voorwaarden#245","groep":"Website","titel":"Algemene voorwaarden: Artikel 6. Vergoeding, facturering en betaling","bron":"/voorwaarden","tags":"","tekst":"6.1 De Vergoeding per maand voor de aangekruiste werkzaamheden en het uurtarief voor extra werk staan in de Opdrachtbevestiging. Alle bedragen zijn exclusief btw; Avezaat & Evers berekent de btw daar bovenop. 6.2 Avezaat & Evers factureert de Vergoeding maandelijks vooraf en extra werk maandelijks achteraf. Zij verstuurt alle facturen op de eerste dag van de maand per e-mail naar het adres van Opdrachtgever uit de Opdrachtbevestiging. Elke factuur bevat een betaallink waarmee Opdrachtgever de factuur kan betalen. Opdrachtgever meldt een nieuw e-mailadres Schriftelijk. 6.3 Opdrachtgever betaalt de Vergoeding en alle andere bedragen uit de Overeenkomst met de betaallink in de factuur. Een betaling geldt als ontvangen op de dag waarop het bedrag is bijgeschreven op de bankrekening van Avezaat & Evers."},
{"id":"voorwaarden#246","groep":"Website","titel":"Algemene voorwaarden: Artikel 6. Vergoeding, facturering en betaling","bron":"/voorwaarden","tags":"","tekst":"Opdrachtgever mag een betaling niet opschorten of verrekenen met een eigen vordering op Avezaat & Evers. 6.4 De betalingstermijn van elke factuur is 14 dagen na de factuurdatum. Die datum is de uiterste betaaldatum; bij een factuur van de eerste dag van de maand is dat de 15e van de maand. 6.5 Werkt de betaallink niet, dan meldt Opdrachtgever dat direct per e-mail aan Avezaat & Evers. Zij biedt dan een andere manier van betalen aan. De betalingstermijn blijft gelden. 6.6 Is een factuur niet binnen de betalingstermijn betaald, dan stuurt Avezaat & Evers Opdrachtgever een betalingsherinnering per e-mail. 6.7 Betaalt Opdrachtgever niet binnen de termijn, dan is Opdrachtgever zonder ingebrekestelling in verzuim. Opdrachtgever is dan de wettelijke handelsrente verschuldigd over het openstaande bedrag, en de buitengerechtelijke incassokosten volgens de wet, met een minimum van € 40."},
{"id":"voorwaarden#247","groep":"Website","titel":"Algemene voorwaarden: Artikel 6. Vergoeding, facturering en betaling","bron":"/voorwaarden","tags":"","tekst":"Ook de redelijke gerechtelijke kosten komen voor rekening van Opdrachtgever. 6.8 Betaalt Opdrachtgever niet binnen 14 dagen na een betalingsherinnering, dan mag Avezaat & Evers haar werkzaamheden opschorten totdat is betaald. Zij is niet aansprakelijk voor gevolgen van deze opschorting, zoals te late aangiftes. De Vergoeding blijft in die periode verschuldigd. 6.9 Bezwaren tegen een factuur meldt Opdrachtgever binnen 14 dagen na de factuurdatum Schriftelijk of per e-mail aan Avezaat & Evers, met een onderbouwing. Het indienen van bezwaar schort de betalingsverplichting voor het onbetwiste deel niet op. 6.10 Avezaat & Evers mag de Vergoeding en het uurtarief eenmaal per jaar verhogen, bijvoorbeeld voor indexering, per 1 januari. Zij meldt de verhoging ten minste 30 dagen vooraf Schriftelijk of per e-mail. Opdrachtgever kan de Overeenkomst altijd opzeggen volgens artikel 7. Een verhoging door een wijziging van btw of andere wettelijke heffingen kan Avezaat & Evers direct doorvoeren."},
{"id":"voorwaarden#248","groep":"Website","titel":"Algemene voorwaarden: Artikel 7. Duur en opzegging","bron":"/voorwaarden","tags":"","tekst":"7.1 De Overeenkomst gaat in op de datum die in de Opdrachtbevestiging staat en loopt voor onbepaalde tijd. Er is geen minimale looptijd en er is geen stilzwijgende verlenging: de Overeenkomst eindigt alleen door opzegging of ontbinding. 7.2 Beide partijen kunnen de Overeenkomst opzeggen met een opzegtermijn van één maand, tegen het einde van een kalendermaand. De opzegtermijn gaat in op de dag waarop de opzegging door de andere partij is ontvangen. De Overeenkomst eindigt aan het einde van de kalendermaand waarin de opzegtermijn afloopt. 7.3 Opzegging gebeurt per e-mail: Opdrachtgever zegt op aan info@avezaatenevers.nl , Avezaat & Evers aan het e-mailadres van Opdrachtgever uit de Opdrachtbevestiging. De ontvanger bevestigt de ontvangst binnen 5 werkdagen en vermeldt de datum waarop de Overeenkomst eindigt. 7.4 Tot en met de einddatum voert Avezaat & Evers de Opdracht uit."},
{"id":"voorwaarden#249","groep":"Website","titel":"Algemene voorwaarden: Artikel 7. Duur en opzegging","bron":"/voorwaarden","tags":"","tekst":"Aangiftes waarvan de wettelijke indieningstermijn na de einddatum verloopt, vallen niet meer onder de Opdracht, tenzij partijen dat vóór de einddatum Schriftelijk anders overeenkomen. Avezaat & Evers werkt redelijkerwijs mee aan een goede overdracht aan een andere boekhouder of aan Opdrachtgever zelf. Voor die overdracht mag zij de bestede uren in rekening brengen tegen het uurtarief uit de Opdrachtbevestiging. 7.5 De Vergoeding wordt per hele maand berekend. Opdrachtgever betaalt de Vergoeding voor de hele maand waarin de Overeenkomst eindigt. Daarna wordt niet meer gefactureerd. Avezaat & Evers verzendt de eindafrekening binnen 14 dagen na het einde van de Overeenkomst."},
{"id":"voorwaarden#250","groep":"Website","titel":"Algemene voorwaarden: Artikel 7. Duur en opzegging","bron":"/voorwaarden","tags":"","tekst":"7.6 Elke partij mag de Overeenkomst met onmiddellijke ingang Schriftelijk beëindigen (ontbinden) als de andere partij ernstig tekortschiet en na een Schriftelijke ingebrekestelling met een redelijke termijn van 14 dagen nalaat dit te herstellen. Dat geldt ook zonder ingebrekestelling bij faillissement, surseance van betaling of wettelijke schuldsanering van de andere partij, en als de andere partij haar onderneming beëindigt. 7.7 Bij beëindiging gelden de afspraken over de teruggave van gegevens in artikel 5.5 en over geheimhouding in artikel 9. 7.8 In afwijking van artikel 7.2 en 7.5 kan Opdrachtgever de Overeenkomst opzeggen in de eerste kalendermaand waarin de Overeenkomst loopt. Opzegging gebeurt per e-mail (artikel 7.3). De Overeenkomst eindigt dan op de dag waarop Avezaat & Evers de opzegging ontvangt, of op een latere dag in die maand die Opdrachtgever in de opzegging noemt."},
{"id":"voorwaarden#251","groep":"Website","titel":"Algemene voorwaarden: Artikel 7. Duur en opzegging","bron":"/voorwaarden","tags":"","tekst":"Avezaat & Evers betaalt de Vergoeding voor die eerste maand binnen 14 dagen na de einddatum volledig terug. Extra werk dat Opdrachtgever heeft laten uitvoeren blijft verschuldigd. De artikelen 5.5 en 7.4 gelden ook bij deze opzegging."},
{"id":"voorwaarden#252","groep":"Website","titel":"Algemene voorwaarden: Artikel 8. Aansprakelijkheid en vrijwaring","bron":"/voorwaarden","tags":"","tekst":"8.1 Avezaat & Evers is alleen aansprakelijk voor schade van Opdrachtgever die het rechtstreekse gevolg is van een toerekenbare tekortkoming in de uitvoering van de Opdracht, en alleen binnen de grenzen van dit artikel. 8.2 De aansprakelijkheid van Avezaat & Evers is per gebeurtenis, en een reeks samenhangende gebeurtenissen geldt als één gebeurtenis, beperkt tot het bedrag dat haar beroepsaansprakelijkheidsverzekering in het betreffende geval uitkeert, vermeerderd met het eigen risico. Keert de verzekeraar om welke reden dan ook niet uit, dan is de aansprakelijkheid beperkt tot de Vergoeding die Avezaat & Evers in de 12 maanden vóór de gebeurtenis heeft ontvangen, met een maximum van € TBA."},
{"id":"voorwaarden#253","groep":"Website","titel":"Algemene voorwaarden: Artikel 8. Aansprakelijkheid en vrijwaring","bron":"/voorwaarden","tags":"","tekst":"8.3 Avezaat & Evers is niet aansprakelijk voor indirecte schade, zoals gederfde winst, gemiste besparingen, schade door bedrijfsstagnatie, en schade door te late of onjuiste aangiftes die het gevolg is van de aangeleverde Stukken of van het niet nakomen van artikel 4 door Opdrachtgever. 8.4 Boetes, naheffingen, belastingrente en kosten van de Belastingdienst die het gevolg zijn van een fout van Avezaat & Evers komen voor vergoeding in aanmerking binnen het maximum van artikel 8.2, tenzij Avezaat & Evers de fout tijdig kon herstellen en Opdrachtgever dat niet heeft gedaan. Boetes of naheffingen die het gevolg zijn van gegevens die Opdrachtgever niet, onjuist of te laat heeft aangeleverd, zijn voor rekening van Opdrachtgever."},
{"id":"voorwaarden#254","groep":"Website","titel":"Algemene voorwaarden: Artikel 8. Aansprakelijkheid en vrijwaring","bron":"/voorwaarden","tags":"","tekst":"8.5 De beperkingen in dit artikel gelden niet bij opzet of bewuste roekeloosheid van Avezaat & Evers of van haar leidinggevenden, en niet voor zover de wet een beperking niet toestaat. 8.6 Opdrachtgever meldt een klacht of schade binnen 30 dagen na ontdekking Schriftelijk aan Avezaat & Evers, met een duidelijke omschrijving. Meldt Opdrachtgever dat niet tijdig, dan kan Avezaat & Evers zich erop beroepen dat Opdrachtgever te laat heeft geklaagd. Een vordering tot schadevergoeding vervalt 12 maanden na de dag waarop Opdrachtgever de schade ontdekte of redelijkerwijs kon ontdekken. 8.7 Opdrachtgever vrijwaart Avezaat & Evers tegen aanspraken van derden die verband houden met de uitvoering van de Opdracht, tenzij de schade het gevolg is van opzet of bewuste roekeloosheid van Avezaat & Evers. 8.8 De beperkingen in dit artikel gelden ook voor de derden die Avezaat & Evers bij de uitvoering inschakelt, zoals een mede-vennoot, een medewerker of een ingehuurde kracht. Zij mogen zich daar rechtstreeks op beroepen."},
{"id":"voorwaarden#255","groep":"Website","titel":"Algemene voorwaarden: Artikel 9. Geheimhouding en privacy","bron":"/voorwaarden","tags":"","tekst":"9.1 Partijen houden alle vertrouwelijke informatie die zij van elkaar ontvangen geheim, en gebruiken die alleen voor de uitvoering van de Overeenkomst. Voor Avezaat & Evers gaat het onder meer om financiële gegevens, bankgegevens, loon- en personeelsgegevens en overige bedrijfsgevoelige informatie van Opdrachtgever. 9.2 Avezaat & Evers mag vertrouwelijke informatie alleen delen met personen die er voor de uitvoering van de Opdracht toegang toe moeten hebben en die aan dezelfde geheimhouding gebonden zijn, zoals een mede-vennoot of een ingeschakelde derde. 9.3 De geheimhouding geldt niet voor informatie die al openbaar is, en niet voor zover een wettelijke plicht of een uitspraak van een rechter of een toezichthouder tot openbaarmaking verplicht. Avezaat & Evers informeert Opdrachtgever daar vooraf over, tenzij dat niet is toegestaan."},
{"id":"voorwaarden#256","groep":"Website","titel":"Algemene voorwaarden: Artikel 9. Geheimhouding en privacy","bron":"/voorwaarden","tags":"","tekst":"9.4 De geheimhouding blijft ook na het einde van de Overeenkomst gelden, gedurende 5 jaar. 9.5 Avezaat & Evers verwerkt persoonsgegevens van Opdrachtgever zelf voor de uitvoering van de Overeenkomst, het factureren en incasseren van de Vergoeding en het nakomen van wettelijke verplichtingen. Opdrachtgever ontvangt vooraf de privacyverklaring van Avezaat & Evers en heeft de rechten die de wet geeft, zoals inzage, correctie en verwijdering, voor zover de wet dat toelaat. 9.6 Verwerkt Avezaat & Evers bij de uitvoering van de Opdracht persoonsgegevens van derden, zoals klanten, leveranciers of medewerkers van Opdrachtgever, dan is Opdrachtgever de verwerkingsverantwoordelijke en Avezaat & Evers de verwerker. Partijen sluiten daarvoor een verwerkersovereenkomst, die als bijlage bij de Opdrachtbevestiging hoort."},
{"id":"voorwaarden#257","groep":"Website","titel":"Algemene voorwaarden: Artikel 9. Geheimhouding en privacy","bron":"/voorwaarden","tags":"","tekst":"Avezaat & Evers verwerkt deze gegevens alleen op instructie van Opdrachtgever, neemt passende beveiligingsmaatregelen, schakelt andere verwerkers (zoals MoneyMonk) alleen in volgens de verwerkersovereenkomst en meldt een datalek zonder onredelijke vertraging aan Opdrachtgever. 9.7 Wettelijke bewaartermijnen gaan voor. Avezaat & Evers bewaart administratieve gegevens zolang de wet dat vereist (in het algemeen zeven jaar), ook na het einde van de Overeenkomst. 9.8 In afwijking van artikel 9.2 geeft Opdrachtgever Avezaat & Evers toestemming om gegevens te delen met partijen die dat voor de uitvoering van de Opdracht nodig hebben, zoals de Belastingdienst, MoneyMonk, banken en andere ingeschakelde derden. Avezaat & Evers deelt niet meer gegevens dan daarvoor nodig is."},
{"id":"voorwaarden#258","groep":"Website","titel":"Algemene voorwaarden: Artikel 10. Overmacht, wijzigingen, klachten, geschillen en slotbepalingen","bron":"/voorwaarden","tags":"","tekst":"10.1 Een tekortkoming die niet aan Avezaat & Evers kan worden toegerekend (overmacht) verplicht haar niet tot schadevergoeding. Onder overmacht vallen onder meer: storing of onbeschikbaarheid van MoneyMonk of andere software van derden, storing van internet of stroom, ziekte of arbeidsongeschiktheid van een vennoot of medewerker, overheidsmaatregelen en andere omstandigheden buiten de macht van Avezaat & Evers. Zij informeert Opdrachtgever zo spoedig mogelijk over de overmacht en de verwachte duur. Duurt de overmacht langer dan 30 dagen, dan kan Opdrachtgever de Overeenkomst kosteloos en met onmiddellijke ingang opzeggen. De Vergoeding voor de periode waarin Avezaat & Evers niet kon leveren, wordt naar rato verrekend of terugbetaald."},
{"id":"voorwaarden#259","groep":"Website","titel":"Algemene voorwaarden: Artikel 10. Overmacht, wijzigingen, klachten, geschillen en slotbepalingen","bron":"/voorwaarden","tags":"","tekst":"10.2 Wijzigingen of aanvullingen op de Overeenkomst, zoals het toevoegen of schrappen van werkzaamheden, zijn alleen geldig als beide partijen ze Schriftelijk of per e-mail hebben bevestigd, behalve de prijsverhoging uit artikel 6.10. Avezaat & Evers legt nieuwe werkzaamheden en de Vergoeding vast in een nieuwe Opdrachtbevestiging of in een bevestigingsmail. 10.3 Avezaat & Evers mag deze algemene voorwaarden wijzigen. Zij meldt een wijziging ten minste 30 dagen vóór de ingangsdatum Schriftelijk aan Opdrachtgever. Is de wijziging van betekenis nadelig voor Opdrachtgever, dan kan hij tot de ingangsdatum de Overeenkomst opzeggen met ingang van die datum. Doet hij dat niet, dan gelden de gewijzigde voorwaarden vanaf de ingangsdatum. Wijzigingen die de wet verplicht stelt, kunnen zonder deze opzegmogelijkheid worden doorgevoerd."},
{"id":"voorwaarden#260","groep":"Website","titel":"Algemene voorwaarden: Artikel 10. Overmacht, wijzigingen, klachten, geschillen en slotbepalingen","bron":"/voorwaarden","tags":"","tekst":"10.4 De Overeenkomst is een overeenkomst van opdracht en geen arbeidsovereenkomst. Tussen partijen bestaat geen gezagsverhouding. Avezaat & Evers bepaalt zelf hoe, wanneer en met welke middelen zij de Opdracht uitvoert, binnen de afspraken in de Overeenkomst, en draagt zelf zorg voor haar verzekeringen, middelen, belastingen en premies. 10.5 Opdrachtgever dient een klacht in per e-mail bij info@avezaatenevers.nl . Avezaat & Evers bevestigt de klacht binnen 5 werkdagen en reageert inhoudelijk binnen 14 dagen. Is een inhoudelijke reactie in die termijn niet mogelijk, dan meldt zij wanneer Opdrachtgever antwoord krijgt. Een klacht schort de betalingsverplichting voor het onbetwiste deel niet op. 10.6 Komen partijen er niet uit, dan zoeken zij binnen 30 dagen een oplossing via overleg tussen de vennoten van Avezaat & Evers en Opdrachtgever."},
{"id":"voorwaarden#261","groep":"Website","titel":"Algemene voorwaarden: Artikel 10. Overmacht, wijzigingen, klachten, geschillen en slotbepalingen","bron":"/voorwaarden","tags":"","tekst":"Lukt dat niet, dan beslist de bevoegde rechter van de rechtbank Rotterdam. 10.7 Op de Overeenkomst is Nederlands recht van toepassing. 10.8 Partijen mogen de Overeenkomst elektronisch aangaan en ondertekenen. Een elektronische handtekening is even geldig als een handgeschreven handtekening. 10.9 Is een bepaling van deze algemene voorwaarden nietig of vernietigbaar, dan blijven de overige bepalingen van kracht. Partijen vervangen de bepaling door een geldige bepaling die zoveel mogelijk dezelfde strekking heeft. 10.10 Opdrachtgever mag zijn rechten en verplichtingen uit de Overeenkomst niet overdragen aan een derde zonder Schriftelijke toestemming van Avezaat & Evers. 10.11 De Overeenkomst wordt aangegaan met Avezaat & Evers en niet met een individuele vennoot of medewerker. Opdrachtgever kan niet eisen dat een bepaalde persoon de Opdracht uitvoert."},
{"id":"voorwaarden#262","groep":"Website","titel":"Algemene voorwaarden: Artikel 10. Overmacht, wijzigingen, klachten, geschillen en slotbepalingen","bron":"/voorwaarden","tags":"","tekst":"Treedt een vennoot uit, wordt hij arbeidsongeschikt of overlijdt hij, dan loopt de Overeenkomst door met de andere vennoot of vennoten van Avezaat & Evers. Kan geen van de vennoten de Opdracht nog uitvoeren, dan werkt Avezaat & Evers redelijkerwijs mee aan een goede overdracht aan een andere boekhouder, zoals bepaald in artikel 7.4. Artikel 10.1 (overmacht) kan dan van toepassing zijn. 10.12 Avezaat & Evers mag de Overeenkomst met alle rechten en verplichtingen overdragen aan een rechtsopvolger, bijvoorbeeld wanneer zij haar onderneming omzet in of inbrengt in een besloten vennootschap. Opdrachtgever geeft daarvoor bij voorbaat toestemming. Avezaat & Evers meldt de overdracht Schriftelijk aan Opdrachtgever. De Opdrachtbevestiging en deze algemene voorwaarden blijven dan van kracht."},
{"id":"voorwaarden#263","groep":"Website","titel":"Algemene voorwaarden: Artikel 10. Overmacht, wijzigingen, klachten, geschillen en slotbepalingen","bron":"/voorwaarden","tags":"","tekst":"Is de overdracht van betekenis nadelig voor Opdrachtgever, dan kan hij de Overeenkomst opzeggen met ingang van de datum van overdracht. 10.13 Deze algemene voorwaarden zijn vastgesteld op 28 oktober 2026 (versie 1.0). De meest recente versie staat op avezaatenevers.nl/ voorwaarden.html . Bij een wijziging geldt artikel 10.3."}];
